package com.fasterxml.jackson.databind.type;

import com.fasterxml.jackson.databind.JavaType;
import org.junit.Test;
import static org.junit.Assert.*;

import java.lang.reflect.Field;

public class TypeParserTest {

    private static final TypeFactory TYPE_FACTORY = TypeFactory.defaultInstance();

    // Access constants via reflection since they are protected
    private static final int MAX_TYPE_LENGTH;
    private static final int MAX_TYPE_NESTING;

    static {
        try {
            Field maxLengthField = TypeParser.class.getDeclaredField("MAX_TYPE_LENGTH");
            maxLengthField.setAccessible(true);
            MAX_TYPE_LENGTH = maxLengthField.getInt(null);

            Field maxNestingField = TypeParser.class.getDeclaredField("MAX_TYPE_NESTING");
            maxNestingField.setAccessible(true);
            MAX_TYPE_NESTING = maxNestingField.getInt(null);
        } catch (Exception e) {
            throw new RuntimeException(e);
        }
    }

    @Test
    public void testParseWithinLimits() {
        TypeParser parser = new TypeParser(TYPE_FACTORY);
        JavaType type = parser.parse("java.util.List<java.lang.String>");
        assertNotNull(type);
        assertEquals("java.util.List", type.getRawClass().getName());
        assertEquals(1, type.containedTypeCount());
        assertEquals(String.class, type.containedType(0).getRawClass());
    }

    @Test
    public void testParseExceedsMaxLength() {
        TypeParser parser = new TypeParser(TYPE_FACTORY);
        // Build a string longer than MAX_TYPE_LENGTH
        StringBuilder sb = new StringBuilder();
        // Start with a base class
        sb.append("java.util.List<");
        // Add many parameters to exceed the limit
        while (sb.length() <= MAX_TYPE_LENGTH) {
            sb.append("java.lang.String,");
        }
        sb.append("java.lang.Integer>");
        String longType = sb.toString();

        try {
            parser.parse(longType);
            fail("Expected IllegalArgumentException for too long type string");
        } catch (IllegalArgumentException e) {
            // Check that the error message contains the truncated type and the max length
            assertTrue(e.getMessage().contains("too long"));
            assertTrue(e.getMessage().contains(String.valueOf(MAX_TYPE_LENGTH)));
            // Also check that the message includes the truncated representation
            assertTrue(e.getMessage().contains("..."));
        }
    }

    @Test
    public void testParseExceedsMaxNesting() {
        TypeParser parser = new TypeParser(TYPE_FACTORY);
        // Build a deeply nested type string
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < MAX_TYPE_NESTING + 1; i++) {
            sb.append("java.util.List<");
        }
        sb.append("java.lang.String");
        for (int i = 0; i < MAX_TYPE_NESTING + 1; i++) {
            sb.append(">");
        }
        String deeplyNested = sb.toString();

        try {
            parser.parse(deeplyNested);
            fail("Expected IllegalArgumentException for too deeply nested type");
        } catch (IllegalArgumentException e) {
            assertTrue(e.getMessage().contains("too deeply nested"));
            assertTrue(e.getMessage().contains(String.valueOf(MAX_TYPE_NESTING)));
        }
    }

    @Test
    public void testQuoteTruncated() throws Exception {
        // Use reflection to invoke the private method
        java.lang.reflect.Method method = TypeParser.class.getDeclaredMethod("_quoteTruncated", String.class);
        method.setAccessible(true);

        // Test with short string
        String shortStr = "Hello";
        String result = (String) method.invoke(null, shortStr);
        assertEquals("'Hello'", result);

        // Test with string of length 1000
        StringBuilder exact = new StringBuilder();
        for (int i = 0; i < 1000; i++) {
            exact.append("a");
        }
        String exactStr = exact.toString();
        result = (String) method.invoke(null, exactStr);
        assertEquals("'" + exactStr + "'", result);

        // Test with string longer than 1000
        StringBuilder longer = new StringBuilder();
        for (int i = 0; i < 1500; i++) {
            longer.append("b");
        }
        String longerStr = longer.toString();
        result = (String) method.invoke(null, longerStr);
        // Should be truncated to first 1000 chars and have suffix
        assertTrue(result.startsWith("'bbbb"));
        assertTrue(result.contains("..."));
        assertTrue(result.contains("truncated 500 charaters"));
        // Note: there's a typo in the patch: "charaters" instead of "characters". We'll match as is.
    }
}

