package com.fasterxml.jackson.databind.deser.std;

import com.fasterxml.jackson.core.JsonProcessingException;
import com.fasterxml.jackson.databind.DeserializationFeature;
import com.fasterxml.jackson.databind.JsonMappingException;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.exc.MismatchedInputException;
import org.junit.Test;

import java.io.IOException;
import java.util.Date;

import static org.junit.Assert.*;

public class StdDeserializerNestedArrayTest {
    private final ObjectMapper MAPPER = new ObjectMapper()
            .enable(DeserializationFeature.UNWRAP_SINGLE_VALUE_ARRAYS);

    // Helper method to assert that nested array throws an exception
    private void assertNestedArrayFails(String json, Class<?> targetType) throws IOException {
        try {
            MAPPER.readValue(json, targetType);
            fail("Expected an exception for nested array with " + targetType);
        } catch (JsonMappingException e) {
            // Expected
            // The error message should contain "nested Arrays not allowed"
            assertTrue(e.getMessage().contains("nested Arrays not allowed"));
        }
    }

    // Test for boolean
    @Test
    public void testBooleanPrimitiveNestedArray() throws IOException {
        // Single wrapped array should work
        boolean value = MAPPER.readValue("[true]", boolean.class);
        assertTrue(value);

        // Nested array should fail
        assertNestedArrayFails("[[true]]", boolean.class);
    }

    @Test
    public void testBooleanWrapperNestedArray() throws IOException {
        // Single wrapped array should work
        Boolean value = MAPPER.readValue("[true]", Boolean.class);
        assertTrue(value);

        // Nested array should fail
        assertNestedArrayFails("[[true]]", Boolean.class);
    }

    // Test for byte
    @Test
    public void testBytePrimitiveNestedArray() throws IOException {
        byte value = MAPPER.readValue("[42]", byte.class);
        assertEquals(42, value);

        assertNestedArrayFails("[[42]]", byte.class);
    }

    @Test
    public void testByteWrapperNestedArray() throws IOException {
        Byte value = MAPPER.readValue("[42]", Byte.class);
        assertEquals(Byte.valueOf((byte)42), value);

        assertNestedArrayFails("[[42]]", Byte.class);
    }

    // Test for short
    @Test
    public void testShortPrimitiveNestedArray() throws IOException {
        short value = MAPPER.readValue("[42]", short.class);
        assertEquals(42, value);

        assertNestedArrayFails("[[42]]", short.class);
    }

    @Test
    public void testShortWrapperNestedArray() throws IOException {
        Short value = MAPPER.readValue("[42]", Short.class);
        assertEquals(Short.valueOf((short)42), value);

        assertNestedArrayFails("[[42]]", Short.class);
    }

    // Test for int
    @Test
    public void testIntPrimitiveNestedArray() throws IOException {
        int value = MAPPER.readValue("[42]", int.class);
        assertEquals(42, value);

        assertNestedArrayFails("[[42]]", int.class);
    }

    @Test
    public void testIntegerWrapperNestedArray() throws IOException {
        Integer value = MAPPER.readValue("[42]", Integer.class);
        assertEquals(Integer.valueOf(42), value);

        assertNestedArrayFails("[[42]]", Integer.class);
    }

    // Test for long
    @Test
    public void testLongPrimitiveNestedArray() throws IOException {
        long value = MAPPER.readValue("[42]", long.class);
        assertEquals(42L, value);

        assertNestedArrayFails("[[42]]", long.class);
    }

    @Test
    public void testLongWrapperNestedArray() throws IOException {
        Long value = MAPPER.readValue("[42]", Long.class);
        assertEquals(Long.valueOf(42L), value);

        assertNestedArrayFails("[[42]]", Long.class);
    }

    // Test for float
    @Test
    public void testFloatPrimitiveNestedArray() throws IOException {
        float value = MAPPER.readValue("[3.14]", float.class);
        assertEquals(3.14f, value, 0.001f);

        assertNestedArrayFails("[[3.14]]", float.class);
    }

    @Test
    public void testFloatWrapperNestedArray() throws IOException {
        Float value = MAPPER.readValue("[3.14]", Float.class);
        assertEquals(Float.valueOf(3.14f), value);

        assertNestedArrayFails("[[3.14]]", Float.class);
    }

    // Test for double
    @Test
    public void testDoublePrimitiveNestedArray() throws IOException {
        double value = MAPPER.readValue("[3.14]", double.class);
        assertEquals(3.14, value, 0.001);

        assertNestedArrayFails("[[3.14]]", double.class);
    }

    @Test
    public void testDoubleWrapperNestedArray() throws IOException {
        Double value = MAPPER.readValue("[3.14]", Double.class);
        assertEquals(Double.valueOf(3.14), value);

        assertNestedArrayFails("[[3.14]]", Double.class);
    }

    // Test for java.util.Date
    @Test
    public void testDateNestedArray() throws IOException {
        // Date deserialization from array with a single number (timestamp) or string
        // We'll use a timestamp
        long timestamp = 1665619200000L; // 2022-10-13
        Date expected = new Date(timestamp);
        Date value = MAPPER.readValue("[" + timestamp + "]", Date.class);
        assertEquals(expected, value);

        // Nested array should fail
        try {
            MAPPER.readValue("[[" + timestamp + "]]", Date.class);
            fail("Expected an exception for nested array with Date");
        } catch (JsonMappingException e) {
            assertTrue(e.getMessage().contains("nested Arrays not allowed"));
        }
    }

    // Additional test: without UNWRAP_SINGLE_VALUE_ARRAYS, nested arrays might fail differently.
    @Test
    public void testWithoutUnwrapSingleValueArrays() throws IOException {
        ObjectMapper mapper = new ObjectMapper()
                .disable(DeserializationFeature.UNWRAP_SINGLE_VALUE_ARRAYS);
        // Without the feature, an array is not expected for a scalar.
        // This should throw a MismatchedInputException (or JsonMappingException)
        try {
            mapper.readValue("[true]", boolean.class);
            fail("Expected an exception without UNWRAP_SINGLE_VALUE_ARRAYS");
        } catch (MismatchedInputException e) {
            // Expected
        }
    }
}

