package com.fasterxml.jackson.databind.deser.std;

import com.fasterxml.jackson.annotation.JsonCreator;
import com.fasterxml.jackson.annotation.JsonFormat;
import com.fasterxml.jackson.annotation.JsonProperty;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.Test;

import java.util.Arrays;
import java.util.Objects;

import static org.junit.Assert.assertEquals;

public class FactoryBasedEnumDeserializerTest {

    @JsonFormat(shape = JsonFormat.Shape.OBJECT)
    enum AEnum {
        A("AType"),
        B("BType");

        private final String type;

        AEnum(String type) {
            this.type = type;
        }

        public String getType() {
            return type;
        }

        @JsonCreator(mode = JsonCreator.Mode.DELEGATING)
        public static AEnum fromString(String type) {
            return Arrays.stream(values())
                    .filter(aEnum -> aEnum.type.equals(type))
                    .findFirst()
                    .orElseThrow(() -> new IllegalArgumentException("Unknown type: " + type));
        }

        @JsonCreator(mode = JsonCreator.Mode.PROPERTIES)
        public static AEnum create(@JsonProperty("type") String type) {
            return fromString(type);
        }
    }

    @Test
    public void testEnumWithBothDelegatingAndPropertiesCreators() throws Exception {
        ObjectMapper mapper = new ObjectMapper();

        // Test properties-based creator with JSON object
        AEnum result1 = mapper.readValue("{ \"type\": \"AType\" }", AEnum.class);
        assertEquals(AEnum.A, result1);

        // Test delegating creator with JSON string
        AEnum result2 = mapper.readValue("\"AType\"", AEnum.class);
        assertEquals(AEnum.A, result2);
    }

    // Also test a POJO for comparison (should already work)
    static class AClass {
        private final String name;

        AClass(String name) {
            this.name = name;
        }

        public String getName() {
            return name;
        }

        @JsonCreator(mode = JsonCreator.Mode.DELEGATING)
        public static AClass fromString(String name) {
            return new AClass(name);
        }

        @JsonCreator(mode = JsonCreator.Mode.PROPERTIES)
        public static AClass create(@JsonProperty("name") String name) {
            return new AClass(name);
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (o == null || getClass() != o.getClass()) return false;
            AClass aClass = (AClass) o;
            return Objects.equals(name, aClass.name);
        }

        @Override
        public int hashCode() {
            return Objects.hash(name);
        }
    }

    @Test
    public void testClassWithBothDelegatingAndPropertiesCreators() throws Exception {
        ObjectMapper mapper = new ObjectMapper();

        AClass result1 = mapper.readValue("{ \"name\": \"someName\" }", AClass.class);
        assertEquals(new AClass("someName"), result1);

        AClass result2 = mapper.readValue("\"someName\"", AClass.class);
        assertEquals(new AClass("someName"), result2);
    }
}

