package com.fasterxml.jackson.databind.ext;

import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.Test;
import javax.xml.namespace.QName;
import static org.junit.Assert.*;

public class CoreXMLDeserializersTest {

    private final ObjectMapper MAPPER = new ObjectMapper();

    @Test
    public void testQNameDeserializationFromEmptyString() throws Exception {
        // Test empty string -> should return empty QName (not null)
        QName qname = MAPPER.readValue("\"\"", QName.class);
        assertNotNull("Deserialized QName should not be null", qname);
        assertEquals("Local part should be empty", "", qname.getLocalPart());
        // Also check that namespace URI and prefix are empty (as per QName.valueOf(""))
        assertEquals("Namespace URI should be empty", "", qname.getNamespaceURI());
        assertEquals("Prefix should be empty", "", qname.getPrefix());
    }

    @Test
    public void testQNameDeserializationFromNonEmptyString() throws Exception {
        // Ensure normal deserialization still works
        QName qname = MAPPER.readValue("\"a\"", QName.class);
        assertNotNull(qname);
        assertEquals("a", qname.getLocalPart());
        // Default namespace and prefix are empty for a simple string
        assertEquals("", qname.getNamespaceURI());
        assertEquals("", qname.getPrefix());
    }

    @Test
    public void testQNameDeserializationWithNamespace() throws Exception {
        // Test a QName with namespace (format: {namespaceURI}localPart)
        String json = "\"{http://example.com}local\"";
        QName qname = MAPPER.readValue(json, QName.class);
        assertNotNull(qname);
        assertEquals("local", qname.getLocalPart());
        assertEquals("http://example.com", qname.getNamespaceURI());
        // Prefix is not set in this representation
        assertEquals("", qname.getPrefix());
    }

    // Optional: test coercion actions if needed, but the main issue is empty string.
}

