import javax.xml.namespace.QName;
import java.io.IOException;

import static org.junit.Assert.*;

public class CoreXMLDeserializersTest {

    @Test
    public void testEmptyQNameDeserialization() throws IOException {
        ObjectMapper mapper = new ObjectMapper();

        // Test empty string should deserialize to empty QName, not null
        QName result = mapper.readValue("\"\"", QName.class);
        assertNotNull("Empty string should deserialize to non-null QName", result);
        assertTrue("Result should be instance of QName", result instanceof QName);
        assertEquals("Local part should be empty string", "", result.getLocalPart());
        assertEquals("Namespace URI should be empty string", "", result.getNamespaceURI());
        assertEquals("Prefix should be empty string", "", result.getPrefix());
    }

    @Test
    public void testNonEmptyQNameDeserialization() throws IOException {
        ObjectMapper mapper = new ObjectMapper();

        // Test non-empty QName deserialization still works
        QName result = mapper.readValue("\"a\"", QName.class);
        assertNotNull(result);
        assertEquals("a", result.getLocalPart());
        assertEquals("", result.getNamespaceURI());
        assertEquals("", result.getPrefix());
    }

    @Test
    public void testQNameWithNamespaceDeserialization() throws IOException {
        ObjectMapper mapper = new ObjectMapper();

        // Test QName with namespace prefix
        QName result = mapper.readValue("\"{http://example.com}local\"", QName.class);
        assertNotNull(result);
        assertEquals("local", result.getLocalPart());
        assertEquals("http://example.com", result.getNamespaceURI());
        assertEquals("", result.getPrefix());
    }

    @Test
    public void testDirectDeserializerUsage() throws IOException {
        // Create an instance of the internal Std deserializer for QName
        CoreXMLDeserializers.Std deserializer = new CoreXMLDeserializers.Std(QName.class, CoreXMLDeserializers.TYPE_QNAME);

        // Create a mock DeserializationContext
        ObjectMapper mapper = new ObjectMapper();
        DeserializationContext ctxt = mapper.getDeserializationContext();

        // Test _deserializeFromEmptyString method directly
        Object result = deserializer._deserializeFromEmptyString(ctxt);
        assertNotNull("_deserializeFromEmptyString should return non-null for QName", result);
        assertTrue("Result should be QName", result instanceof QName);

        QName qname = (QName) result;
        assertEquals("Local part should be empty", "", qname.getLocalPart());
        assertEquals("Should be the shared EMPTY_QNAME instance", CoreXMLDeserializers.EMPTY_QNAME, result);
    }

    @Test
    public void testEmptyQNameEquality() throws IOException {
        ObjectMapper mapper = new ObjectMapper();

        QName qname1 = mapper.readValue("\"\"", QName.class);
        QName qname2 = mapper.readValue("\"\"", QName.class);

        assertNotNull(qname1);
        assertNotNull(qname2);
        assertEquals("Multiple empty QName deserializations should be equal", qname1, qname2);
        assertEquals("Local parts should both be empty", qname1.getLocalPart(), qname2.getLocalPart());
    }
}

