        // primary namespace is null, so should take secondary
        assertEquals("simple1", merged.getSimpleName());
        assertEquals("ns2", merged.getNamespace());
    }

    @Test
    public void testMergeIdentityOptimization() {
        PropertyName name1 = new PropertyName("simple", "ns");
        PropertyName name2 = new PropertyName("", "");
        // When merging, if the result is exactly name1, return name1
        PropertyName merged = PropertyName.merge(name1, name2);
        assertSame(name1, merged);
        // Also the other way: if name2 is empty and name1 has values, merging name2 and name1 should return name1?
        // Actually, merge(name2, name1) -> primary is name2 (empty), secondary is name1 (non-empty).
        // The result should be name1, but the identity optimization may not kick in because the merged
        // simple and namespace are from name1, but the ns and simple strings are the same as name1's.
        // Let's test:
        PropertyName merged2 = PropertyName.merge(name2, name1);
        // The merged result should have same content as name1, but may be a new instance.
        // However, the optimization checks if ns and simple are the same object references.
        // Since name2 has empty strings, _nonEmpty returns name1's strings, which are the same references.
        // So the condition (ns == name1._namespace && simple == name1._simpleName) is true, and returns name1.
        // Actually, wait: the primary is name2, secondary is name1. The merge method first checks nulls, then:
        // ns = _nonEmpty(name2._namespace, name1._namespace) -> returns name1._namespace
        // simple = _nonEmpty(name2._simpleName, name1._simpleName) -> returns name1._simpleName
        // Then it checks if (ns == name2._namespace && simple == name2._simpleName) -> false
        // Then if (ns == name1._namespace && simple == name1._simpleName) -> true, so returns name1.
        // So it should return name1.
        assertSame(name1, merged2);
    }

    @Test
    public void testMergeWithUseDefault() {
