        // According to merge logic: primary is USE_DEFAULT, secondary is name.
        // USE_DEFAULT._simpleName = "" (empty), _namespace = null.
        // So _nonEmpty for simple: primary empty -> returns secondary simple -> "simple"
        // _nonEmpty for namespace: primary null -> returns secondary namespace -> "ns"
        // Then check identity: ns == USE_DEFAULT._namespace? null vs "ns" -> false.
        // Then check if ns == name._namespace and simple == name._simpleName -> true, so returns name.
        PropertyName merged = PropertyName.merge(useDefault, name);
        assertSame(name, merged);
        // Reverse: primary is name, secondary is USE_DEFAULT.
        // primary has non-empty simple and namespace, so they are used.
        // Then identity check: ns == name._namespace and simple == name._simpleName -> true, returns name.
        PropertyName merged2 = PropertyName.merge(name, useDefault);
        assertSame(name, merged2);
    }

    @Test
    public void testMergeNoName() {
        // PropertyName.NO_NAME has empty simple name (but a special instance) and null namespace.
        PropertyName noName = PropertyName.NO_NAME;
        PropertyName name = new PropertyName("simple", "ns");
        // Similar to USE_DEFAULT, but NO_NAME is a different instance.
        PropertyName merged = PropertyName.merge(noName, name);
        // Should return name because primary empty/null -> use secondary.
        // And identity optimization should return name.
        assertSame(name, merged);
        // Reverse
        PropertyName merged2 = PropertyName.merge(name, noName);
        assertSame(name, merged2);
    }

    @Test
    public void testMergeBothEmpty() {
