        // Then check identity: ns == empty1._namespace? both are empty strings, but are they the same object? In Java, empty string literals are interned? Not guaranteed.
        // However, the PropertyName constructor uses InternCache for simpleName, but namespace is not interned.
        // So we cannot rely on reference equality. The method may create a new instance.
        // We'll just check content.
        assertEquals("", merged.getSimpleName());
        assertEquals("", merged.getNamespace());
        // It might be a new instance, so we don't assert same.
    }

    @Test
    public void testMergeNamespaceNonEmptyTakesPrecedence() {
        // Test that non-empty namespace from primary is used even if secondary has one.
        PropertyName name1 = new PropertyName("simple", "ns1");
        PropertyName name2 = new PropertyName("simple", "ns2");
        PropertyName merged = PropertyName.merge(name1, name2);
        assertEquals("ns1", merged.getNamespace());
        // If primary namespace is empty, use secondary.
        PropertyName name3 = new PropertyName("simple", "");
        PropertyName merged2 = PropertyName.merge(name3, name2);
        assertEquals("ns2", merged2.getNamespace());
        // If primary namespace is null, use secondary.
        PropertyName name4 = new PropertyName("simple", null);
        PropertyName merged3 = PropertyName.merge(name4, name2);
        assertEquals("ns2", merged3.getNamespace());
    }
}

