package com.fasterxml.jackson.databind.deser.std;

import com.fasterxml.jackson.annotation.JsonAnyGetter;
import com.fasterxml.jackson.annotation.JsonAnySetter;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.Test;

import java.util.HashMap;
import java.util.Map;

import static org.junit.Assert.*;

/**
 * Test for {@link ThrowableDeserializer} to verify fix for NPE when deserializing
 * a Throwable with @JsonAnySetter.
 *
 * @see <a href="https://github.com/FasterXML/jackson-databind/issues/4316">Issue 4316</a>
 */
public class ThrowableDeserializerTest {

    static class Problem extends Exception {
        @JsonAnySetter
        @JsonAnyGetter
        Map<String, Object> additionalProperties = new HashMap<>();

        // Default constructor for deserialization
        public Problem() {
            super();
        }

        // Constructor with message
        public Problem(String message) {
            super(message);
        }

        // Constructor with message and cause
        public Problem(String message, Throwable cause) {
            super(message, cause);
        }
    }

    @Test
    public void testDeserializeThrowableWithAnySetter() throws Exception {
        ObjectMapper mapper = new ObjectMapper();

        // Create an instance and add an additional property
        Problem original = new Problem("test message");
        original.additionalProperties.put("additional", "value");

        // Serialize
        String json = mapper.writeValueAsString(original);
        // Deserialize
        Problem deserialized = mapper.readValue(json, Problem.class);

        // Verify
        assertNotNull(deserialized);
        assertEquals("test message", deserialized.getMessage());
        assertNotNull(deserialized.additionalProperties);
        assertEquals("value", deserialized.additionalProperties.get("additional"));
    }

    @Test
    public void testDeserializeThrowableWithAnySetterWithoutMessage() throws Exception {
        ObjectMapper mapper = new ObjectMapper();

        // Create an instance without a message, but with additional property
        Problem original = new Problem();
        original.additionalProperties.put("extra", 42);

        // Serialize
        String json = mapper.writeValueAsString(original);
        // Deserialize
        Problem deserialized = mapper.readValue(json, Problem.class);

        // Verify
        assertNotNull(deserialized);
        assertNull(deserialized.getMessage());
        assertNotNull(deserialized.additionalProperties);
        assertEquals(42, deserialized.additionalProperties.get("extra"));
    }

    @Test
    public void testDeserializeThrowableWithAnySetterAndNullMessage() throws Exception {
        ObjectMapper mapper = new ObjectMapper();

        // Create an instance with null message and additional property
        Problem original = new Problem(null);
        original.additionalProperties.put("key", "value");

        // Serialize
        String json = mapper.writeValueAsString(original);
        // Deserialize
        Problem deserialized = mapper.readValue(json, Problem.class);

        // Verify
        assertNotNull(deserialized);
        assertNull(deserialized.getMessage());
        assertNotNull(deserialized.additionalProperties);
        assertEquals("value", deserialized.additionalProperties.get("key"));
    }

    @Test
    public void testDeserializeThrowableWithAnySetterAndMultipleAdditional() throws Exception {
        ObjectMapper mapper = new ObjectMapper();

        // Create an instance with multiple additional properties
        Problem original = new Problem("msg");
        original.additionalProperties.put("a", 1);
        original.additionalProperties.put("b", "two");
        original.additionalProperties.put("c", true);

        // Serialize
        String json = mapper.writeValueAsString(original);
        // Deserialize
        Problem deserialized = mapper.readValue(json, Problem.class);

        // Verify
        assertNotNull(deserialized);
        assertEquals("msg", deserialized.getMessage());
        assertNotNull(deserialized.additionalProperties);
        assertEquals(3, deserialized.additionalProperties.size());
        assertEquals(1, deserialized.additionalProperties.get("a"));
        assertEquals("two", deserialized.additionalProperties.get("b"));
        assertEquals(true, deserialized.additionalProperties.get("c"));
    }
}

