package com.fasterxml.jackson.databind.node;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.Test;
import static org.junit.Assert.*;

public class ObjectNodeWithObjectTest {

    @Test
    public void testWithObjectWithJsonPointer() {
        ObjectMapper mapper = new ObjectMapper();
        ObjectNode root = mapper.createObjectNode();

        // Test with valid JsonPointer expression - should create nested objects
        ObjectNode result = root.withObject("/a/b/c");
        assertNotNull(result);
        assertTrue(root.has("a"));
        JsonNode aNode = root.get("a");
        assertTrue(aNode.isObject());
        ObjectNode aObj = (ObjectNode) aNode;
        assertTrue(aObj.has("b"));
        JsonNode bNode = aObj.get("b");
        assertTrue(bNode.isObject());
        ObjectNode bObj = (ObjectNode) bNode;
        assertTrue(bObj.has("c"));
        JsonNode cNode = bObj.get("c");
        assertTrue(cNode.isObject());

        // Verify the returned node is the same as the deepest created node
        assertSame(cNode, result);
    }

    @Test
    public void testWithObjectWithPropertyName() {
        ObjectMapper mapper = new ObjectMapper();
        ObjectNode root = mapper.createObjectNode();

        // Test with property name (not a JsonPointer) - should create direct child
        ObjectNode result = root.withObject("address");
        assertNotNull(result);
        assertTrue(root.has("address"));
        assertSame(result, root.get("address"));
        assertTrue(result.isObject());

        // Add some data to verify it's a proper object node
        result.put("street", "123 Main St");
        assertEquals("123 Main St", root.get("address").get("street").asText());
    }

    @Test
    public void testWithObjectWithEmptyString() {
        ObjectMapper mapper = new ObjectMapper();
        ObjectNode root = mapper.createObjectNode();

        // Empty string is a valid JsonPointer (points to root)
        // Should return the root node itself
        ObjectNode result = root.withObject("");
        assertSame(root, result);
    }

    @Test
    public void testWithObjectWithExistingProperty() {
        ObjectMapper mapper = new ObjectMapper();
        ObjectNode root = mapper.createObjectNode();

        // Create an existing object property
        ObjectNode existing = root.putObject("profile");
        existing.put("name", "John");

        // Calling withObject with property name should return existing node
        ObjectNode result = root.withObject("profile");
        assertSame(existing, result);
        assertEquals("John", result.get("name").asText());

        // Calling withObject with JsonPointer to existing property
        ObjectNode result2 = root.withObject("/profile");
        assertSame(existing, result2);
    }

    @Test
    public void testWithObjectWithMixedPath() {
        ObjectMapper mapper = new ObjectMapper();
        ObjectNode root = mapper.createObjectNode();

        // Create partial path
        ObjectNode a = root.putObject("a");
        ObjectNode b = a.putObject("b");

        // Use JsonPointer to extend existing path
        ObjectNode result = root.withObject("/a/b/c");
        assertNotNull(result);
        assertTrue(b.has("c"));
        assertSame(result, b.get("c"));

        // Use property name at root level
