package com.fasterxml.jackson.databind;

import com.fasterxml.jackson.databind.node.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class JsonNodeWithPropertyTest {

    @Test
    public void testWithObjectPropertyOnObjectNode() {
        ObjectNode root = JsonNodeFactory.instance.objectNode();

        // When property doesn't exist, should create new ObjectNode
        ObjectNode child1 = root.withObjectProperty("newObj");
        assertNotNull(child1);
        assertTrue(child1.isObject());
        assertSame(child1, root.get("newObj"));

        // When property exists and is ObjectNode, should return it
        ObjectNode child2 = root.withObjectProperty("newObj");
        assertSame(child1, child2);

        // When property exists and is NullNode, should replace with ObjectNode
        root.putNull("nullProp");
        ObjectNode child3 = root.withObjectProperty("nullProp");
        assertNotNull(child3);
        assertTrue(child3.isObject());
        assertSame(child3, root.get("nullProp"));
    }

    @Test(expected = UnsupportedOperationException.class)
    public void testWithObjectPropertyOnNonObjectNode() {
        ArrayNode array = JsonNodeFactory.instance.arrayNode();
        array.withObjectProperty("prop");
    }

    @Test
    public void testWithArrayPropertyOnObjectNode() {
        ObjectNode root = JsonNodeFactory.instance.objectNode();

        // When property doesn't exist, should create new ArrayNode
        ArrayNode child1 = root.withArrayProperty("newArr");
        assertNotNull(child1);
        assertTrue(child1.isArray());
        assertSame(child1, root.get("newArr"));

        // When property exists and is ArrayNode, should return it
        ArrayNode child2 = root.withArrayProperty("newArr");
        assertSame(child1, child2);

        // When property exists and is NullNode, should replace with ArrayNode
        root.putNull("nullArr");
        ArrayNode child3 = root.withArrayProperty("nullArr");
        assertNotNull(child3);
        assertTrue(child3.isArray());
        assertSame(child3, root.get("nullArr"));
    }

    @Test(expected = UnsupportedOperationException.class)
    public void testWithArrayPropertyOnNonObjectNode() {
        ArrayNode array = JsonNodeFactory.instance.arrayNode();
        array.withArrayProperty("prop");
    }

    @Test(expected = UnsupportedOperationException.class)
    public void testWithObjectPropertyOnValueNode() {
        TextNode text = JsonNodeFactory.instance.textNode("test");
        text.withObjectProperty("prop");
    }

    @Test(expected = UnsupportedOperationException.class)
    public void testWithArrayPropertyOnValueNode() {
        TextNode text = JsonNodeFactory.instance.textNode("test");
        text.withArrayProperty("prop");
    }

    @Test
    public void testWithObjectPropertyRejectsNonObjectExistingValue() {
        ObjectNode root = JsonNodeFactory.instance.objectNode();
        root.put("text", "value");

        try {
            root.withObjectProperty("text");
            fail("Should have thrown exception for non-object existing value");
        } catch (UnsupportedOperationException e) {
            assertTrue(e.getMessage().contains("Cannot replace"));
            assertTrue(e.getMessage().contains("TextNode"));
            assertTrue(e.getMessage().contains("ObjectNode"));
        }
    }

    @Test
    public void testWithArrayPropertyRejectsNonArrayExistingValue() {
        ObjectNode root = JsonNodeFactory.instance.objectNode();
        root.put("num", 42);

        try {
            root.withArrayProperty("num");
            fail("Should have thrown exception for non-array existing value");
        } catch (UnsupportedOperationException e) {
            assertTrue(e.getMessage().contains("Cannot replace"));
            assertTrue(e.getMessage().contains("IntNode"));
            assertTrue(e.getMessage().contains("ArrayNode"));
        }
    }

    @Test
    public void testWithObjectPropertyOnEmptyObjectNode() {
        ObjectNode root = JsonNodeFactory.instance.objectNode();
        ObjectNode child = root.withObjectProperty("child");
        assertNotNull(child);
        assertEquals(1, root.size());
        assertSame(child, root.get("child"));
    }

    @Test
    public void testWithArrayPropertyOnEmptyObjectNode() {
        ObjectNode root = JsonNodeFactory.instance.objectNode();
        ArrayNode child = root.withArrayProperty("child");
        assertNotNull(child);
        assertEquals(1, root.size());
        assertSame(child, root.get("child"));
    }

    @Test
    public void testWithObjectPropertyChain() {
        ObjectNode root = JsonNodeFactory.instance.objectNode();
        ObjectNode child1 = root.withObjectProperty("level1");
        ObjectNode child2 = child1.withObjectProperty("level2");
        ArrayNode child3 = child2.withArrayProperty("level3");

        assertNotNull(child1);
        assertNotNull(child2);
        assertNotNull(child3);
        assertEquals(1, root.size());
        assertEquals(1, child1.size());
        assertEquals(1, child2.size());
        assertTrue(child3.isEmpty());
    }

    @Test
    public void testWithArrayPropertyAddElements() {
        ObjectNode root = JsonNodeFactory.instance.objectNode();
        ArrayNode array = root.withArrayProperty("items");
        array.add("item1");
        array.add(123);

        assertEquals(2, array.size());
        assertEquals("item1", array.get(0).asText());
        assertEquals(123, array.get(1).asInt());

        // Getting the same array should preserve elements
        ArrayNode sameArray = root.withArrayProperty("items");
        assertEquals(2, sameArray.size());
        assertSame(array, sameArray);
    }
}

