package com.fasterxml.jackson.databind.deser.std;

import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.core.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class ThrowableDeserializerTest {

    // Test for issue #4071: custom Throwable without single-String constructor
    // should ignore "message" property during deserialization
    public static class CustomException extends Exception {
        public CustomException() {
            super();
        }
    }

    @Test
    public void testDeserializeCustomThrowableWithMessageProperty() throws Exception {
        ObjectMapper mapper = new ObjectMapper();

        // Create JSON with "message" property (typical serialization output)
        String json = "{\"message\":\"test message\",\"suppressed\":[],\"localizedMessage\":\"test message\"}";

        // Deserialize should succeed without UnrecognizedPropertyException
        CustomException exception = mapper.readValue(json, CustomException.class);

        // Verify the exception was created (message may be null since we're using default constructor)
        assertNotNull(exception);
        // The message should be null since we're using default constructor and ignoring the "message" property
        assertNull(exception.getMessage());
    }

    @Test
    public void testDeserializeCustomThrowableWithOnlyMessageProperty() throws Exception {
        ObjectMapper mapper = new ObjectMapper();

        // Minimal JSON with just message property
        String json = "{\"message\":\"test\"}";

        CustomException exception = mapper.readValue(json, CustomException.class);
        assertNotNull(exception);
        assertNull(exception.getMessage());
    }

    @Test
    public void testDeserializeCustomThrowableWithMixedProperties() throws Exception {
        ObjectMapper mapper = new ObjectMapper();

        // JSON with message and other standard Throwable properties
        String json = "{\"message\":\"error\",\"suppressed\":[],\"localizedMessage\":\"error\",\"stackTrace\":[]}";

        CustomException exception = mapper.readValue(json, CustomException.class);
        assertNotNull(exception);
        assertNull(exception.getMessage());
    }

    @Test
    public void testDeserializeCustomThrowableWithUnknownPropertyFails() throws Exception {
        ObjectMapper mapper = new ObjectMapper();

        // JSON with message and an unknown property - should fail on unknown property
        String json = "{\"message\":\"test\",\"unknownField\":\"value\"}";

        try {
            mapper.readValue(json, CustomException.class);
            fail("Should have thrown UnrecognizedPropertyException for unknown field");
        } catch (JsonMappingException e) {
            // Expected - unknown property should still cause failure
            assertTrue(e.getMessage().contains("unknownField"));
        }
    }

    @Test
    public void testDeserializeThrowableWithStringConstructor() throws Exception {
        // Exception with single-String constructor should work as before
        ObjectMapper mapper = new ObjectMapper();

        String json = "{\"message\":\"test message\"}";
        Exception exception = mapper.readValue(json, Exception.class);

        assertNotNull(exception);
        assertEquals("test message", exception.getMessage());
    }

    @Test
    public void testDeserializeWithSuppressedProperty() throws Exception {
        ObjectMapper mapper = new ObjectMapper();

        // JSON with suppressed array
        String json = "{\"message\":\"test\",\"suppressed\":[{\"message\":\"suppressed1\"},{\"message\":\"suppressed2\"}]}";

        CustomException exception = mapper.readValue(json, CustomException.class);
        assertNotNull(exception);
        // Suppressed exceptions should be added
        assertEquals(2, exception.getSuppressed().length);
    }

    @Test
    public void testCaseInsensitiveMessageProperty() throws Exception {
        ObjectMapper mapper = new ObjectMapper();

        // Test with different case variations of "message"
        String[] variations = {"message", "Message", "MESSAGE", "mEsSaGe"};

        for (String propName : variations) {
            String json = String.format("{\"%s\":\"test\"}", propName);
            CustomException exception = mapper.readValue(json, CustomException.class);
            assertNotNull(exception);
            assertNull(exception.getMessage());
        }
    }
}

