package com.fasterxml.jackson.databind.cfg;

import com.fasterxml.jackson.databind.DeserializationConfig;
import com.fasterxml.jackson.databind.MapperFeature;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.type.LogicalType;
import com.fasterxml.jackson.databind.cfg.CoercionAction;
import com.fasterxml.jackson.databind.cfg.CoercionConfigs;
import com.fasterxml.jackson.databind.cfg.CoercionInputShape;
import org.junit.Test;

import static org.junit.Assert.*;

public class CoercionConfigsTest {

    @Test
    public void testFindCoercionWithAllowCoercionOfScalarsDisabledAndIntToFloat() {
        // Create a CoercionConfigs instance with default settings
        CoercionConfigs configs = new CoercionConfigs();

        // Create a DeserializationConfig with ALLOW_COERCION_OF_SCALARS disabled
        DeserializationConfig config = new ObjectMapper().getDeserializationConfig()
                .without(MapperFeature.ALLOW_COERCION_OF_SCALARS);

        // Test integer to float coercion: should NOT return Fail because it's exempted
        CoercionAction action = configs.findCoercion(
                config,
                LogicalType.Float,
                Float.class,
                CoercionInputShape.Integer
        );

        // With the patch, integer to float coercion should be allowed even when ALLOW_COERCION_OF_SCALARS is disabled
        assertNotEquals("Integer to Float coercion should not fail when ALLOW_COERCION_OF_SCALARS is disabled", 
                CoercionAction.Fail, action);
    }

    @Test
    public void testFindCoercionWithAllowCoercionOfScalarsDisabledAndNonIntToFloat() {
        // Create a CoercionConfigs instance with default settings
        CoercionConfigs configs = new CoercionConfigs();

        // Create a DeserializationConfig with ALLOW_COERCION_OF_SCALARS disabled
        DeserializationConfig config = new ObjectMapper().getDeserializationConfig()
                .without(MapperFeature.ALLOW_COERCION_OF_SCALARS);

        // Test other scalar coercions: should return Fail
        CoercionAction action = configs.findCoercion(
                config,
                LogicalType.Integer,
                Integer.class,
                CoercionInputShape.EmptyString
        );

        // For non-integer-to-float coercions, when ALLOW_COERCION_OF_SCALARS is disabled, should fail
        assertEquals("EmptyString to Integer coercion should fail when ALLOW_COERCION_OF_SCALARS is disabled", 
                CoercionAction.Fail, action);
    }

    @Test
    public void testFindCoercionWithAllowCoercionOfScalarsEnabledAndIntToFloat() {
        // Create a CoercionConfigs instance with default settings
        CoercionConfigs configs = new CoercionConfigs();

        // Create a DeserializationConfig with ALLOW_COERCION_OF_SCALARS enabled (default)
        DeserializationConfig config = new ObjectMapper().getDeserializationConfig()
                .with(MapperFeature.ALLOW_COERCION_OF_SCALARS);

        // Test integer to float coercion: should be allowed
        CoercionAction action = configs.findCoercion(
                config,
                LogicalType.Float,
                Float.class,
                CoercionInputShape.Integer
        );

        // With ALLOW_COERCION_OF_SCALARS enabled, integer to float should be allowed
        assertNotEquals("Integer to Float coercion should not fail when ALLOW_COERCION_OF_SCALARS is enabled", 
                CoercionAction.Fail, action);
    }

    @Test
    public void testFindCoercionWithAllowCoercionOfScalarsDisabledAndFloatToFloat() {
        // Create a CoercionConfigs instance with default settings
        CoercionConfigs configs = new CoercionConfigs();

        // Create a DeserializationConfig with ALLOW_COERCION_OF_SCALARS disabled
        DeserializationConfig config = new ObjectMapper().getDeserializationConfig()
                .without(MapperFeature.ALLOW_COERCION_OF_SCALARS);

        // Test float to float coercion (not integer shape): should return Fail
        CoercionAction action = configs.findCoercion(
                config,
                LogicalType.Float,
                Float.class,
                CoercionInputShape.Float
        );

        // Float to Float with Float input shape is not exempted, so should fail
        assertEquals("Float to Float coercion with Float input shape should fail when ALLOW_COERCION_OF_SCALARS is disabled", 
                CoercionAction.Fail, action);
    }

    @Test
    public void testFindCoercionWithAllowCoercionOfScalarsDisabledAndIntToNonFloatScalar() {
        // Create a CoercionConfigs instance with default settings
        CoercionConfigs configs = new CoercionConfigs();

        // Create a DeserializationConfig with ALLOW_COERCION_OF_SCALARS disabled
        DeserializationConfig config = new ObjectMapper().getDeserializationConfig()
                .without(MapperFeature.ALLOW_COERCION_OF_SCALARS);

        // Test integer to integer coercion: should return Fail
        CoercionAction action = configs.findCoercion(
                config,
