import com.fasterxml.jackson.databind.deser.std.DateDeserializers;
import org.junit.Test;
import java.io.IOException;
import java.util.Date;
import static org.junit.Assert.*;

public class StdDeserializerNestedArrayTest {

    private final ObjectMapper mapper = new ObjectMapper()
            .enable(DeserializationFeature.UNWRAP_SINGLE_VALUE_ARRAYS);

    // Helper to assert that deserialization fails with nested array
    private void assertNestedArrayFails(String json, Class<?> targetType) throws Exception {
        try {
            mapper.readValue(json, targetType);
            fail("Expected JsonMappingException for nested array in " + targetType.getSimpleName());
        } catch (JsonMappingException e) {
            // Expected
            // Optionally check the message contains "nested Arrays not allowed"
            assertTrue(e.getMessage().contains("nested Arrays not allowed"));
        }
    }

    @Test
    public void testBooleanPrimitiveWithNestedArray() throws Exception {
        assertNestedArrayFails("[[true]]", boolean.class);
    }

    @Test
    public void testBooleanWrapperWithNestedArray() throws Exception {
        assertNestedArrayFails("[[true]]", Boolean.class);
    }

    @Test
    public void testBytePrimitiveWithNestedArray() throws Exception {
        assertNestedArrayFails("[[42]]", byte.class);
    }

    @Test
    public void testByteWrapperWithNestedArray() throws Exception {
        assertNestedArrayFails("[[42]]", Byte.class);
    }

    @Test
    public void testShortPrimitiveWithNestedArray() throws Exception {
        assertNestedArrayFails("[[42]]", short.class);
    }

    @Test
    public void testShortWrapperWithNestedArray() throws Exception {
        assertNestedArrayFails("[[42]]", Short.class);
    }

    @Test
    public void testIntPrimitiveWithNestedArray() throws Exception {
        assertNestedArrayFails("[[42]]", int.class);
    }

    @Test
    public void testIntegerWrapperWithNestedArray() throws Exception {
        assertNestedArrayFails("[[42]]", Integer.class);
    }

    @Test
    public void testLongPrimitiveWithNestedArray() throws Exception {
        assertNestedArrayFails("[[42]]", long.class);
    }

    @Test
    public void testLongWrapperWithNestedArray() throws Exception {
        assertNestedArrayFails("[[42]]", Long.class);
    }

    @Test
    public void testFloatPrimitiveWithNestedArray() throws Exception {
        assertNestedArrayFails("[[3.14]]", float.class);
    }

    @Test
    public void testFloatWrapperWithNestedArray() throws Exception {
        assertNestedArrayFails("[[3.14]]", Float.class);
    }

    @Test
    public void testDoublePrimitiveWithNestedArray() throws Exception {
        assertNestedArrayFails("[[3.14]]", double.class);
    }

    @Test
    public void testDoubleWrapperWithNestedArray() throws Exception {
        assertNestedArrayFails("[[3.14]]", Double.class);
    }

    @Test
    public void testDateWithNestedArray() throws Exception {
        // Date deserialization from number or string
        // We'll use a timestamp number
        assertNestedArrayFails("[[1000000]]", Date.class);
        // Also test with string date
        assertNestedArrayFails("[[\"2022-01-01\"]]", Date.class);
    }

    // Test a custom deserializer that uses _deserializeWrappedValue
    // We'll create a simple class with a custom deserializer that extends StdDeserializer
    public static class CustomValue {
        public String value;
    }

    public static class CustomValueDeserializer extends StdDeserializer<CustomValue> {
        public CustomValueDeserializer() {
            super(CustomValue.class);
        }

        @Override
        public CustomValue deserialize(JsonParser p, DeserializationContext ctxt) throws IOException {
            CustomValue cv = new CustomValue();
            cv.value = p.getText();
            return cv;
        }

        // This method uses _deserializeWrappedValue if we call it, but we don't directly.
        // Instead, we can test by having a field that uses UNWRAP_SINGLE_VALUE_ARRAYS.
        // But to directly test _deserializeWrappedValue, we need to call it.
        // Alternatively, we can test via a class that has a field of type CustomValue with @JsonDeserialize.
    }

    // Instead, we can test a POJO with a field that is a primitive and uses UNWRAP_SINGLE_VALUE_ARRAYS globally.
    // But we already tested primitives.

    // Let's test a POJO with a primitive field to ensure nested arrays are caught when deserializing the POJO.
    public static class PrimitiveFieldBean {
        public int value;
    }

    @Test
    public void testPrimitiveFieldInBeanWithNestedArray() throws Exception {
        try {
            mapper.readValue("{\"value\":[[42]]}", PrimitiveFieldBean.class);
            fail("Expected JsonMappingException for nested array in field");
        } catch (JsonMappingException e) {
            assertTrue(e.getMessage().contains("nested Arrays not allowed"));
        }
    }

    // Additionally, test that single unwrapping still works (non-nested array)
    @Test
    public void testSingleUnwrapStillWorks() throws Exception {
        // Boolean
        assertEquals(true, mapper.readValue("[true]", boolean.class));
        // Integer - need to cast to (int) to resolve ambiguous method call
        assertEquals(42, (int) mapper.readValue("[42]", int.class));
        // Date
        Date date = mapper.readValue("[1000000]", Date.class);
        assertNotNull(date);
        // etc.
    }
}

