                .setCoercion(CoercionInputShape.Integer, CoercionAction.Fail);

        // Test primitive float
        try {
            mapper.readValue("{\"value\": 42}", FloatField.class);
            fail("Expected MismatchedInputException");
        } catch (MismatchedInputException e) {
            // expected
        }

        // Test Float wrapper
        try {
            mapper.readValue("{\"value\": 42}", FloatWrapperField.class);
            fail("Expected MismatchedInputException");
        } catch (MismatchedInputException e) {
            // expected
        }

        // Test primitive double
        try {
            mapper.readValue("{\"value\": 42}", DoubleField.class);
            fail("Expected MismatchedInputException");
        } catch (MismatchedInputException e) {
            // expected
        }

