package com.fasterxml.jackson.databind.introspect;

import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.cfg.MapperConfig;
import com.fasterxml.jackson.databind.PropertyName;
import com.fasterxml.jackson.databind.introspect.AnnotationIntrospectorPair;
import com.fasterxml.jackson.databind.introspect.AnnotatedClass;
import com.fasterxml.jackson.core.Version;
import org.junit.Test;
import static org.junit.Assert.*;

public class AnnotationIntrospectorPairPropertyNameMergeTest {

    // Mock introspectors to test merging behavior
    private static class MockIntrospectorPrimary extends AnnotationIntrospector {
        private final PropertyName rootName;
        private final PropertyName wrapperName;
        private final PropertyName serializationName;
        private final PropertyName deserializationName;

        MockIntrospectorPrimary(PropertyName rootName, PropertyName wrapperName,
                               PropertyName serializationName, PropertyName deserializationName) {
            this.rootName = rootName;
            this.wrapperName = wrapperName;
            this.serializationName = serializationName;
            this.deserializationName = deserializationName;
        }

        @Override
        public PropertyName findRootName(AnnotatedClass ac) {
            return rootName;
        }

        @Override
        public PropertyName findWrapperName(Annotated ann) {
            return wrapperName;
        }

        @Override
        public PropertyName findNameForSerialization(Annotated a) {
            return serializationName;
        }

        @Override
        public PropertyName findNameForDeserialization(Annotated a) {
            return deserializationName;
        }

        @Override
        public Version version() {
            return Version.unknownVersion();
        }
    }

    private static class MockIntrospectorSecondary extends AnnotationIntrospector {
        private final PropertyName rootName;
        private final PropertyName wrapperName;
        private final PropertyName serializationName;
        private final PropertyName deserializationName;

        MockIntrospectorSecondary(PropertyName rootName, PropertyName wrapperName,
                                 PropertyName serializationName, PropertyName deserializationName) {
            this.rootName = rootName;
            this.wrapperName = wrapperName;
            this.serializationName = serializationName;
            this.deserializationName = deserializationName;
        }

        @Override
        public PropertyName findRootName(AnnotatedClass ac) {
            return rootName;
        }

        @Override
        public PropertyName findWrapperName(Annotated ann) {
            return wrapperName;
        }

        @Override
        public PropertyName findNameForSerialization(Annotated a) {
            return serializationName;
        }

        @Override
        public PropertyName findNameForDeserialization(Annotated a) {
            return deserializationName;
        }

        @Override
        public Version version() {
            return Version.unknownVersion();
        }
    }

    @Test
    public void testFindRootNameMerge() {
        // Test case 1: primary has simple name, secondary has namespace
        PropertyName primaryRoot = new PropertyName("root", null);
        PropertyName secondaryRoot = new PropertyName(null, "http://example.com");
        AnnotationIntrospectorPair pair = new AnnotationIntrospectorPair(
            new MockIntrospectorPrimary(primaryRoot, null, null, null),
            new MockIntrospectorSecondary(secondaryRoot, null, null, null)
        );
        PropertyName result = pair.findRootName(null);
        assertNotNull(result);
        assertEquals("root", result.getSimpleName());
        assertEquals("http://example.com", result.getNamespace());

        // Test case 2: primary has namespace, secondary has simple name
        primaryRoot = new PropertyName(null, "http://primary.com");
        secondaryRoot = new PropertyName("secondaryRoot", null);
        pair = new AnnotationIntrospectorPair(
            new MockIntrospectorPrimary(primaryRoot, null, null, null),
            new MockIntrospectorSecondary(secondaryRoot, null, null, null)
        );
        result = pair.findRootName(null);
        assertNotNull(result);
        assertEquals("secondaryRoot", result.getSimpleName());
        assertEquals("http://primary.com", result.getNamespace());

        // Test case 3: primary empty simple name, secondary has simple name
        primaryRoot = new PropertyName("", "http://primary.com");
        secondaryRoot = new PropertyName("validName", null);
        pair = new AnnotationIntrospectorPair(
            new MockIntrospectorPrimary(primaryRoot, null, null, null),
            new MockIntrospectorSecondary(secondaryRoot, null, null, null)
        );
        result = pair.findRootName(null);
        assertNotNull(result);
        assertEquals("validName", result.getSimpleName());
        assertEquals("http://primary.com", result.getNamespace());

        // Test case 4: both null
        pair = new AnnotationIntrospectorPair(
            new MockIntrospectorPrimary(null, null, null, null),
            new MockIntrospectorSecondary(null, null, null, null)
        );
        result = pair.findRootName(null);
        assertNull(result);
    }

    @Test
    public void testFindWrapperNameMerge() {
        // Test case: primary has USE_DEFAULT, secondary has explicit name
        PropertyName primaryWrapper = PropertyName.USE_DEFAULT;
        PropertyName secondaryWrapper = new PropertyName("wrapper", "http://example.com");
        AnnotationIntrospectorPair pair = new AnnotationIntrospectorPair(
            new MockIntrospectorPrimary(null, primaryWrapper, null, null),
            new MockIntrospectorSecondary(null, secondaryWrapper, null, null)
        );
        PropertyName result = pair.findWrapperName(null);
        assertNotNull(result);
        assertEquals("wrapper", result.getSimpleName());
        assertEquals("http://example.com", result.getNamespace());

        // Test case: primary has explicit name, secondary has USE_DEFAULT
        primaryWrapper = new PropertyName("primaryWrapper", null);
        secondaryWrapper = PropertyName.USE_DEFAULT;
        pair = new AnnotationIntrospectorPair(
            new MockIntrospectorPrimary(null, primaryWrapper, null, null),
            new MockIntrospectorSecondary(null, secondaryWrapper, null, null)
        );
        result = pair.findWrapperName(null);
        assertNotNull(result);
        assertEquals("primaryWrapper", result.getSimpleName());
        assertNull(result.getNamespace());
    }

    @Test
    public void testFindNameForSerializationMerge() {
        // Test case: primary has empty simple name, secondary has simple name
        PropertyName primaryName = new PropertyName("", "http://primary.com");
        PropertyName secondaryName = new PropertyName("prop", null);
        AnnotationIntrospectorPair pair = new AnnotationIntrospectorPair(
            new MockIntrospectorPrimary(null, null, primaryName, null),
            new MockIntrospectorSecondary(null, null, secondaryName, null)
        );
        PropertyName result = pair.findNameForSerialization(null);
        assertNotNull(result);
        assertEquals("prop", result.getSimpleName());
        assertEquals("http://primary.com", result.getNamespace());

        // Test case: primary has USE_DEFAULT, secondary has explicit name
        primaryName = PropertyName.USE_DEFAULT;
        secondaryName = new PropertyName("serializationName", "http://secondary.com");
        pair = new AnnotationIntrospectorPair(
            new MockIntrospectorPrimary(null, null, primaryName, null),
            new MockIntrospectorSecondary(null, null, secondaryName, null)
        );
        result = pair.findNameForSerialization(null);
        assertNotNull(result);
        assertEquals("serializationName", result.getSimpleName());
        assertEquals("http://secondary.com", result.getNamespace());
    }

    @Test
    public void testFindNameForDeserializationMerge() {
        // Test case: primary has namespace, secondary has simple name
        PropertyName primaryName = new PropertyName(null, "http://primary.com");
        PropertyName secondaryName = new PropertyName("deserializationProp", null);
        AnnotationIntrospectorPair pair = new AnnotationIntrospectorPair(
            new MockIntrospectorPrimary(null, null, null, primaryName),
            new MockIntrospectorSecondary(null, null, null, secondaryName)
        );
        PropertyName result = pair.findNameForDeserialization(null);
        assertNotNull(result);
        assertEquals("deserializationProp", result.getSimpleName());
        assertEquals("http://primary.com", result.getNamespace());

        // Test case: primary has USE_DEFAULT, secondary has explicit name
        primaryName = PropertyName.USE_DEFAULT;
        secondaryName = new PropertyName("deserializationName", "http://secondary.com");
        pair = new AnnotationIntrospectorPair(
            new MockIntrospectorPrimary(null, null, null, primaryName),
            new MockIntrospectorSecondary(null, null, null, secondaryName)
        );
        result = pair.findNameForDeserialization(null);
        assertNotNull(result);
        assertEquals("deserializationName", result.getSimpleName());
