package com.fasterxml.jackson.databind.util;

import org.junit.Test;
import java.util.Optional;
import java.util.OptionalInt;
import java.util.OptionalLong;
import java.util.OptionalDouble;
import com.fasterxml.jackson.databind.JavaType;
import com.fasterxml.jackson.databind.ObjectMapper;
import static org.junit.Assert.*;

public class BeanUtilTest {

    @Test
    public void testIsJava8OptionalClass() {
        // Test with standard Java 8 optional classes
        assertTrue("Optional should be recognized as Java 8 optional",
                BeanUtil.isJava8OptionalClass(Optional.class));
        assertTrue("OptionalInt should be recognized as Java 8 optional",
                BeanUtil.isJava8OptionalClass(OptionalInt.class));
        assertTrue("OptionalLong should be recognized as Java 8 optional",
                BeanUtil.isJava8OptionalClass(OptionalLong.class));
        assertTrue("OptionalDouble should be recognized as Java 8 optional",
                BeanUtil.isJava8OptionalClass(OptionalDouble.class));

        // Test with non-optional classes
        assertFalse("String should not be recognized as Java 8 optional",
                BeanUtil.isJava8OptionalClass(String.class));
        assertFalse("Integer should not be recognized as Java 8 optional",
                BeanUtil.isJava8OptionalClass(Integer.class));
        assertFalse("java.util.ArrayList should not be recognized as Java 8 optional",
                BeanUtil.isJava8OptionalClass(java.util.ArrayList.class));
        assertFalse("java.time.LocalDate should not be recognized as Java 8 optional",
                BeanUtil.isJava8OptionalClass(java.time.LocalDate.class));
    }

    // Additionally, we can test the checkUnsupportedType method to see if it returns the correct message for optional types.
    // However, note that checkUnsupportedType returns a string or null. We'll test that it returns a non-null string for optional types.
    @Test
    public void testCheckUnsupportedTypeForOptional() {
        // Create a JavaType for an optional class. We need to use the ObjectMapper's type factory.
        ObjectMapper mapper = new ObjectMapper();
        com.fasterxml.jackson.databind.type.TypeFactory tf = mapper.getTypeFactory();

        // Test with OptionalInt
        JavaType optionalIntType = tf.constructType(OptionalInt.class);
        String msg = BeanUtil.checkUnsupportedType(optionalIntType);
        assertNotNull("checkUnsupportedType should return a message for OptionalInt", msg);
        assertTrue("Message should contain 'Java 8 optional'", msg.contains("Java 8 optional"));
        assertTrue("Message should suggest jackson-datatype-jdk8", msg.contains("jackson-datatype-jdk8"));

        // Test with Optional
        JavaType optionalType = tf.constructType(Optional.class);
        msg = BeanUtil.checkUnsupportedType(optionalType);
        assertNotNull("checkUnsupportedType should return a message for Optional", msg);
        assertTrue("Message should contain 'Java 8 optional'", msg.contains("Java 8 optional"));
        assertTrue("Message should suggest jackson-datatype-jdk8", msg.contains("jackson-datatype-jdk8"));

        // Test with a non-optional type (should return null)
        JavaType stringType = tf.constructType(String.class);
        assertNull("checkUnsupportedType should return null for String", BeanUtil.checkUnsupportedType(stringType));
    }
}

