package com.fasterxml.jackson.databind.type;

import org.junit.Test;
import static org.junit.Assert.*;

import java.util.*;

import com.fasterxml.jackson.databind.JavaType;

public class TypeParserTest {

    // Helper to create a TypeParser with default TypeFactory
    private TypeParser newParser() {
        return new TypeParser(TypeFactory.defaultInstance());
    }

    // Test that a type string within the length limit parses successfully
    @Test
    public void testParseWithinLengthLimit() {
        TypeParser parser = newParser();
        JavaType type = parser.parse("java.util.List<java.lang.String>");
        assertNotNull(type);
        assertEquals("java.util.List", type.getRawClass().getName());
        assertEquals(1, type.containedTypeCount());
        assertEquals(String.class, type.containedType(0).getRawClass());
    }

    // Test that a type string exceeding MAX_TYPE_LENGTH throws IllegalArgumentException
    @Test
    public void testParseExceedsMaxLength() {
        TypeParser parser = newParser();
        // Build a string longer than 64_000 characters
        StringBuilder sb = new StringBuilder();
        sb.append("java.util.List<");
        for (int i = 0; i < 64000; i++) {
            sb.append("java.lang.String,");
        }
        sb.append("java.lang.String>");
        String longType = sb.toString();
        // Expect exception due to length
        try {
            parser.parse(longType);
            fail("Should have thrown IllegalArgumentException due to length");
        } catch (IllegalArgumentException e) {
            // Verify the message contains the expected truncation and length info
            assertTrue(e.getMessage().contains("too long"));
            assertTrue(e.getMessage().contains("maximum length allowed"));
            // Optionally check that the truncated representation is included
            assertTrue(e.getMessage().contains("..."));
        }
    }

    // Test that a deeply nested type within the nesting limit parses successfully
    @Test
    public void testParseWithinNestingLimit() {
        TypeParser parser = newParser();
        // Build a type with nesting depth 10 (well under 1000)
        String typeStr = buildNestedType(10, "java.lang.String");
        JavaType type = parser.parse(typeStr);
        assertNotNull(type);
        // We can't easily verify the entire structure, but no exception is thrown
    }

    // Test that a type exceeding MAX_TYPE_NESTING throws IllegalArgumentException
    @Test
    public void testParseExceedsMaxNesting() {
        TypeParser parser = newParser();
        // Build a type with nesting depth 1001 (exceeds limit)
        String typeStr = buildNestedType(1001, "java.lang.String");
        try {
            parser.parse(typeStr);
            fail("Should have thrown IllegalArgumentException due to nesting depth");
        } catch (IllegalArgumentException e) {
            // Verify the message mentions nesting and the limit
            assertTrue(e.getMessage().contains("too deeply nested"));
            assertTrue(e.getMessage().contains(""+TypeParser.MAX_TYPE_NESTING));
        }
    }

    // Helper to build a nested parameterized type string
    private String buildNestedType(int depth, String baseType) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < depth; i++) {
            sb.append("java.util.List<");
        }
        sb.append(baseType);
        for (int i = 0; i < depth; i++) {
            sb.append(">");
        }
        return sb.toString();
    }

    // Test the _quoteTruncated method for strings <= 1000 characters
    @Test
    public void testQuoteTruncatedShort() {
        // Use reflection to access private method
        try {
            java.lang.reflect.Method method = TypeParser.class.getDeclaredMethod("_quoteTruncated", String.class);
            method.setAccessible(true);
            String input = "short";
            String result = (String) method.invoke(null, input);
            assertEquals("'short'", result);
        } catch (Exception e) {
            fail("Failed to invoke _quoteTruncated: " + e);
        }
    }

    // Test the _quoteTruncated method for strings > 1000 characters
    @Test
    public void testQuoteTruncatedLong() {
        // Use reflection to access private method
        try {
            java.lang.reflect.Method method = TypeParser.class.getDeclaredMethod("_quoteTruncated", String.class);
            method.setAccessible(true);
            // Build a string longer than 1000 characters
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < 1500; i++) {
                sb.append("a");
            }
            String longInput = sb.toString();
            String result = (String) method.invoke(null, longInput);
            // Should be truncated to first 1000 chars and have "..."
            assertTrue(result.startsWith("'aaaaaaaa"));
            assertTrue(result.contains("..."));
            assertTrue(result.contains("truncated"));
            // The length of the quoted part should be 1000 + overhead
            // We don't need to be exact, just ensure it's truncated
        } catch (Exception e) {
            fail("Failed to invoke _quoteTruncated: " + e);
        }
    }

    // Test that the error message from _problem uses truncated strings when input is long
    @Test
    public void testProblemMessageTruncation() {
        TypeParser parser = newParser();
        // Create a tokenizer with a very long input
        String longInput = buildLongString(2000);
        TypeParser.MyTokenizer tokens = new TypeParser.MyTokenizer(longInput);
        // Simulate an error by calling _problem (protected method, so we use reflection)
        try {
            java.lang.reflect.Method method = TypeParser.class.getDeclaredMethod("_problem", TypeParser.MyTokenizer.class, String.class);
            method.setAccessible(true);
            IllegalArgumentException ex = (IllegalArgumentException) method.invoke(parser, tokens, "test message");
            String msg = ex.getMessage();
            // The message should contain truncated representation
            assertTrue(msg.contains("..."));
            assertTrue(msg.contains("truncated"));
        } catch (Exception e) {
            fail("Failed to invoke _problem: " + e);
        }
    }

    private String buildLongString(int length) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < length; i++) {
            sb.append("a");
        }
        return sb.toString();
    }

    // Additional test to ensure existing functionality still works
    @Test
    public void testParseSimpleType() {
        TypeParser parser = newParser();
        JavaType type = parser.parse("java.lang.String");
        assertNotNull(type);
        assertEquals(String.class, type.getRawClass());
    }

    @Test
    public void testParseParameterizedType() {
        TypeParser parser = newParser();
        JavaType type = parser.parse("java.util.Map<java.lang.String, java.lang.Integer>");
        assertNotNull(type);
        assertEquals(Map.class, type.getRawClass());
        assertEquals(2, type.containedTypeCount());
        assertEquals(String.class, type.containedType(0).getRawClass());
        assertEquals(Integer.class, type.containedType(1).getRawClass());
    }
}

