import java.io.IOException;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.Map;

import static org.junit.Assert.*;

public class Issue3559Test {

    // Test for JsonMappingException._generator and _parser helpers
    @Test
    public void testJsonMappingExceptionFromWithNullContext() {
        // Test that from methods do not throw NPE when context is null
        JsonMappingException e1 = JsonMappingException.from((DeserializationContext) null, "test");
        assertNotNull(e1);
        assertNull(e1.getProcessor());

        JsonMappingException e2 = JsonMappingException.from((DeserializationContext) null, "test", new IOException());
        assertNotNull(e2);
        assertNull(e2.getProcessor());

        JsonMappingException e3 = JsonMappingException.from((SerializerProvider) null, "test");
        assertNotNull(e3);
        assertNull(e3.getProcessor());

        JsonMappingException e4 = JsonMappingException.from((SerializerProvider) null, "test", new IOException());
        assertNotNull(e4);
        assertNull(e4.getProcessor());
    }

    // Test for the main issue: deserialization with null Map field and @JsonAnySetter
    @Test
    public void testAnySetterOnNullMapField() throws IOException {
        ObjectMapper mapper = new ObjectMapper();

        // Test with plain Map field (should become LinkedHashMap)
        String json = "{\"key1\":\"value1\",\"key2\":\"value2\"}";
        BeanWithAnySetterOnMap bean = mapper.readValue(json, BeanWithAnySetterOnMap.class);
        assertNotNull(bean.other);
        assertTrue(bean.other instanceof LinkedHashMap);
        assertEquals(2, bean.other.size());
        assertEquals("value1", bean.other.get("key1"));
        assertEquals("value2", bean.other.get("key2"));

        // Test with HashMap field
        BeanWithAnySetterOnHashMap bean2 = mapper.readValue(json, BeanWithAnySetterOnHashMap.class);
        assertNotNull(bean2.other);
        assertTrue(bean2.other instanceof HashMap);
        assertEquals(2, bean2.other.size());
        assertEquals("value1", bean2.other.get("key1"));
        assertEquals("value2", bean2.other.get("key2"));

        // Test with LinkedHashMap field
        BeanWithAnySetterOnLinkedHashMap bean3 = mapper.readValue(json, BeanWithAnySetterOnLinkedHashMap.class);
        assertNotNull(bean3.other);
        assertTrue(bean3.other instanceof LinkedHashMap);
        assertEquals(2, bean3.other.size());
        assertEquals("value1", bean3.other.get("key1"));
        assertEquals("value2", bean3.other.get("key2"));
    }

    // Test that unsupported Map type throws exception
    @Test(expected = JsonMappingException.class)
    public void testAnySetterOnUnsupportedMap() throws IOException {
        ObjectMapper mapper = new ObjectMapper();
        String json = "{\"key\":\"value\"}";
        mapper.readValue(json, BeanWithAnySetterOnUnsupportedMap.class);
    }

    // Helper classes for testing

    public static class BeanWithAnySetterOnMap {
        @com.fasterxml.jackson.annotation.JsonAnySetter
        public Map<String, String> other; // null initially

        // Note: no default constructor needed? Jackson uses default one.
    }

    public static class BeanWithAnySetterOnHashMap {
        @com.fasterxml.jackson.annotation.JsonAnySetter
        public HashMap<String, String> other;
    }

    public static class BeanWithAnySetterOnLinkedHashMap {
        @com.fasterxml.jackson.annotation.JsonAnySetter
        public LinkedHashMap<String, String> other;
    }

    // Unsupported Map type: TreeMap is not supported by JDKValueInstantiators for default instantiation
    public static class BeanWithAnySetterOnUnsupportedMap {
        @com.fasterxml.jackson.annotation.JsonAnySetter
        public java.util.TreeMap<String, String> other;
    }
}

