package com.fasterxml.jackson.databind.cfg;

import com.fasterxml.jackson.databind.DeserializationConfig;
import com.fasterxml.jackson.databind.DeserializationFeature;
import com.fasterxml.jackson.databind.MapperFeature;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.type.LogicalType;
import org.junit.Test;
import static org.junit.Assert.*;

public class CoercionConfigsTest {

    @Test
    public void testFindCoercionEmptyStringWithAcceptEmptyStringAsNullObjectEnabledForLocale() {
        // Simulate the scenario from issue #4009: Locale deserialization
        // When ACCEPT_EMPTY_STRING_AS_NULL_OBJECT is enabled, empty string for Locale
        // (which is an OtherScalar) should return TryConvert, not AsNull.

        CoercionConfigs configs = new CoercionConfigs();
        ObjectMapper mapper = new ObjectMapper();
        mapper.enable(DeserializationFeature.ACCEPT_EMPTY_STRING_AS_NULL_OBJECT);
        DeserializationConfig config = mapper.getDeserializationConfig();

        // Locale is considered LogicalType.OtherScalar
        CoercionAction action = configs.findCoercion(
                config,
                LogicalType.OtherScalar,
                java.util.Locale.class,
                CoercionInputShape.EmptyString
        );

        // After the fix, for OtherScalar with empty string, it should return TryConvert
        // (which will allow FromStringDeserializer to convert "" to Locale.ROOT)
        assertEquals(CoercionAction.TryConvert, action);
    }

    @Test
    public void testFindCoercionEmptyStringWithAcceptEmptyStringAsNullObjectDisabledForLocale() {
        // When the feature is disabled, OtherScalar should still return TryConvert
        // (backwards compatibility with 2.11)

        CoercionConfigs configs = new CoercionConfigs();
        ObjectMapper mapper = new ObjectMapper();
        mapper.disable(DeserializationFeature.ACCEPT_EMPTY_STRING_AS_NULL_OBJECT);
        DeserializationConfig config = mapper.getDeserializationConfig();

        CoercionAction action = configs.findCoercion(
                config,
                LogicalType.OtherScalar,
                java.util.Locale.class,
                CoercionInputShape.EmptyString
        );

        assertEquals(CoercionAction.TryConvert, action);
    }

    @Test
    public void testFindCoercionEmptyStringForBaseScalarWithAcceptEmptyStringAsNullObjectEnabled() {
        // For base scalar types (like Integer, Float) with the feature enabled,
        // should return AsNull

        CoercionConfigs configs = new CoercionConfigs();
        ObjectMapper mapper = new ObjectMapper();
        mapper.enable(DeserializationFeature.ACCEPT_EMPTY_STRING_AS_NULL_OBJECT);
        DeserializationConfig config = mapper.getDeserializationConfig();

        // Test with Integer (base scalar)
        CoercionAction action = configs.findCoercion(
                config,
                LogicalType.Integer,
                Integer.class,
                CoercionInputShape.EmptyString
        );

        assertEquals(CoercionAction.AsNull, action);
    }

    @Test
    public void testFindCoercionEmptyStringForBaseScalarWithAcceptEmptyStringAsNullObjectDisabled() {
        // For base scalar types with the feature disabled,
        // should return AsNull (since baseScalar is true)

        CoercionConfigs configs = new CoercionConfigs();
        ObjectMapper mapper = new ObjectMapper();
        mapper.disable(DeserializationFeature.ACCEPT_EMPTY_STRING_AS_NULL_OBJECT);
        DeserializationConfig config = mapper.getDeserializationConfig();

        CoercionAction action = configs.findCoercion(
                config,
                LogicalType.Integer,
                Integer.class,
                CoercionInputShape.EmptyString
        );

        assertEquals(CoercionAction.AsNull, action);
    }

    @Test
    public void testFindCoercionEmptyStringForNonScalarWithAcceptEmptyStringAsNullObjectEnabled() {
        // For non-scalar types (like POJO) with the feature enabled,
        // should return AsNull

        CoercionConfigs configs = new CoercionConfigs();
        ObjectMapper mapper = new ObjectMapper();
        mapper.enable(DeserializationFeature.ACCEPT_EMPTY_STRING_AS_NULL_OBJECT);
        DeserializationConfig config = mapper.getDeserializationConfig();

        // Use a non-scalar logical type (e.g., POJO)
        CoercionAction action = configs.findCoercion(
                config,
                LogicalType.POJO,
                Object.class,
                CoercionInputShape.EmptyString
        );

        assertEquals(CoercionAction.AsNull, action);
    }

    @Test
    public void testFindCoercionEmptyStringForNonScalarWithAcceptEmptyStringAsNullObjectDisabled() {
        // For non-scalar types with the feature disabled,
        // should return Fail

        CoercionConfigs configs = new CoercionConfigs();
        ObjectMapper mapper = new ObjectMapper();
        mapper.disable(DeserializationFeature.ACCEPT_EMPTY_STRING_AS_NULL_OBJECT);
        DeserializationConfig config = mapper.getDeserializationConfig();

        CoercionAction action = configs.findCoercion(
                config,
                LogicalType.POJO,
                Object.class,
                CoercionInputShape.EmptyString
        );

        assertEquals(CoercionAction.Fail, action);
    }

    @Test
    public void testFindCoercionEmptyStringForOtherScalarWithCoercionOfScalarsDisabled() {
        // Even when ALLOW_COERCION_OF_SCALARS is disabled, OtherScalar with empty string
        // should still return TryConvert (because the check for baseScalar and
        // ALLOW_COERCION_OF_SCALARS doesn't apply to OtherScalar)

        CoercionConfigs configs = new CoercionConfigs();
        ObjectMapper mapper = new ObjectMapper();
        mapper.disable(MapperFeature.ALLOW_COERCION_OF_SCALARS);
        DeserializationConfig config = mapper.getDeserializationConfig();

        CoercionAction action = configs.findCoercion(
                config,
                LogicalType.OtherScalar,
                java.util.Locale.class,
                CoercionInputShape.EmptyString
        );

        assertEquals(CoercionAction.TryConvert, action);
    }

    @Test
    public void testFindCoercionEmptyStringOrdering() {
        // The key fix in the patch is the ordering: for EmptyString input shape,
        // the check for OtherScalar must come BEFORE the check for baseScalar/ACCEPT_EMPTY_STRING_AS_NULL_OBJECT.
        // This test verifies that ordering.

        CoercionConfigs configs = new CoercionConfigs();
        ObjectMapper mapper = new ObjectMapper();
        mapper.enable(DeserializationFeature.ACCEPT_EMPTY_STRING_AS_NULL_OBJECT);
        DeserializationConfig config = mapper.getDeserializationConfig();

        // For OtherScalar, should get TryConvert (not AsNull)
        CoercionAction action = configs.findCoercion(
                config,
                LogicalType.OtherScalar,
                java.util.Locale.class,
                CoercionInputShape.EmptyString
        );

        // If the ordering is correct, this will be TryConvert.
        // If the ordering were wrong (like before the fix), it would be AsNull.
        assertEquals(CoercionAction.TryConvert, action);
    }
}

