package com.fasterxml.jackson.databind;

import com.fasterxml.jackson.databind.introspect.AnnotationIntrospectorPair;
import com.fasterxml.jackson.databind.introspect.Annotated;
import com.fasterxml.jackson.databind.cfg.MapperConfig;
import com.fasterxml.jackson.databind.introspect.AnnotatedClass;
import com.fasterxml.jackson.databind.introspect.AnnotatedMember;
import com.fasterxml.jackson.databind.introspect.AnnotatedMethod;
import com.fasterxml.jackson.databind.introspect.AnnotatedField;
import com.fasterxml.jackson.core.Version;
import com.fasterxml.jackson.databind.util.ClassUtil;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

import java.lang.annotation.Annotation;

/**
 * Tests for {@link PropertyName#merge} and its usage in {@link AnnotationIntrospectorPair}.
 */
public class PropertyNameMergeTest {

    // Test the helper method _nonEmpty via the public merge method
    @Test
    public void testMergeSimpleNames() {
        // Both null -> null
        assertNull(PropertyName.merge(null, null));

        // First null, second has simple name
        PropertyName pn2 = new PropertyName("simple2");
        assertEquals(pn2, PropertyName.merge(null, pn2));

        // First has simple name, second null
        PropertyName pn1 = new PropertyName("simple1");
        assertEquals(pn1, PropertyName.merge(pn1, null));

        // Both have simple names, first non-empty -> first
        PropertyName merged = PropertyName.merge(pn1, pn2);
        assertEquals("simple1", merged.getSimpleName());

        // First empty simple name, second non-empty -> second
        PropertyName empty = new PropertyName("");
        merged = PropertyName.merge(empty, pn2);
        assertEquals("simple2", merged.getSimpleName());

        // First non-empty, second empty -> first
        merged = PropertyName.merge(pn1, empty);
        assertEquals("simple1", merged.getSimpleName());

        // Both empty -> first (empty)
        PropertyName empty2 = new PropertyName("");
        merged = PropertyName.merge(empty, empty2);
        assertEquals("", merged.getSimpleName());
    }

    @Test
    public void testMergeWithNamespace() {
        // Namespace merging
        PropertyName ns1 = new PropertyName("simple", "ns1");
        PropertyName ns2 = new PropertyName("simple", "ns2");
        // First namespace non-empty, second ignored
        PropertyName merged = PropertyName.merge(ns1, ns2);
        assertEquals("simple", merged.getSimpleName());
        assertEquals("ns1", merged.getNamespace());

        // First namespace null, second non-null -> second
        PropertyName noNs = new PropertyName("simple", null);
        merged = PropertyName.merge(noNs, ns2);
        assertEquals("simple", merged.getSimpleName());
        assertEquals("ns2", merged.getNamespace());

        // First namespace empty string, second non-empty -> second? 
        // According to _nonEmpty, empty string is treated as empty, so second is used.
        PropertyName emptyNs = new PropertyName("simple", "");
        merged = PropertyName.merge(emptyNs, ns2);
        assertEquals("simple", merged.getSimpleName());
        assertEquals("ns2", merged.getNamespace());

        // First namespace non-empty, second null -> first
        merged = PropertyName.merge(ns1, noNs);
        assertEquals("simple", merged.getSimpleName());
        assertEquals("ns1", merged.getNamespace());

        // First namespace non-empty, second empty -> first
        merged = PropertyName.merge(ns1, emptyNs);
        assertEquals("simple", merged.getSimpleName());
        assertEquals("ns1", merged.getNamespace());
    }

    @Test
    public void testMergeUseDefault() {
        // USE_DEFAULT is a special instance with empty simple name and null namespace.
        // It should be treated as empty.
        PropertyName def = PropertyName.USE_DEFAULT;
        PropertyName named = new PropertyName("explicit");
        PropertyName merged = PropertyName.merge(def, named);
        assertEquals("explicit", merged.getSimpleName());
        assertNull(merged.getNamespace());

        // Reverse order: explicit first, default second -> explicit
        merged = PropertyName.merge(named, def);
        assertEquals("explicit", merged.getSimpleName());
        assertNull(merged.getNamespace());

        // Both default -> default (should be same instance? Not required, but should be empty)
        merged = PropertyName.merge(def, def);
        // It may return def or a new instance with empty name.
        assertTrue(merged.isEmpty());
    }

    // Test AnnotationIntrospectorPair merging
    @Test
    public void testAnnotationIntrospectorPairMerge() {
        // Create two custom introspectors
        AnnotationIntrospector primary = new AnnotationIntrospector() {
            @Override
            public PropertyName findNameForSerialization(Annotated a) {
                // Return empty simple name but with namespace
                return new PropertyName("", "primaryNamespace");
            }

            @Override
            public PropertyName findNameForDeserialization(Annotated a) {
                return new PropertyName("primarySimple", null);
            }

            @Override
            public PropertyName findWrapperName(Annotated a) {
                return PropertyName.USE_DEFAULT;
            }

            @Override
            public PropertyName findRootName(AnnotatedClass ac) {
                return new PropertyName("root", null);
            }

            @Override
            public Version version() {
                return Version.unknownVersion();
            }
        };

        AnnotationIntrospector secondary = new AnnotationIntrospector() {
            @Override
            public PropertyName findNameForSerialization(Annotated a) {
                // Return simple name but no namespace
                return new PropertyName("secondarySimple", null);
            }

            @Override
            public PropertyName findNameForDeserialization(Annotated a) {
                return new PropertyName("", "secondaryNamespace");
            }

            @Override
            public PropertyName findWrapperName(Annotated a) {
                return new PropertyName("wrapper", "wrapperNs");
            }

            @Override
            public PropertyName findRootName(AnnotatedClass ac) {
                return new PropertyName("", "secondaryRootNs");
            }

            @Override
            public Version version() {
                return Version.unknownVersion();
            }
        };

        AnnotationIntrospectorPair pair = new AnnotationIntrospectorPair(primary, secondary);

        // For serialization: primary returns empty simple name, secondary returns non-empty -> secondary's simple name, primary's namespace?
        // According to merge: simple name from primary is empty, so secondary's simple name is used.
        // namespace from primary is non-empty, so primary's namespace is used.
        PropertyName result = pair.findNameForSerialization(null);
        assertNotNull(result);
        assertEquals("secondarySimple", result.getSimpleName());
        assertEquals("primaryNamespace", result.getNamespace());

        // For deserialization: primary returns non-empty simple name, secondary returns empty simple name with namespace.
        // simple name from primary is non-empty -> primary's simple name.
        // namespace from primary is null, secondary's namespace is non-empty -> secondary's namespace.
        result = pair.findNameForDeserialization(null);
        assertNotNull(result);
        assertEquals("primarySimple", result.getSimpleName());
        assertEquals("secondaryNamespace", result.getNamespace());

        // For wrapper: primary returns USE_DEFAULT (empty), secondary returns both -> secondary's both.
        result = pair.findWrapperName(null);
        assertNotNull(result);
        assertEquals("wrapper", result.getSimpleName());
        assertEquals("wrapperNs", result.getNamespace());

        // For root name: primary returns non-empty simple name, secondary returns empty simple name with namespace.
        // simple name from primary is non-empty -> primary's simple name.
        // namespace from primary is null, secondary's namespace is non-empty -> secondary's namespace.
        result = pair.findRootName(null);
        assertNotNull(result);
        assertEquals("root", result.getSimpleName());
        assertEquals("secondaryRootNs", result.getNamespace());
    }

    // Additional test to simulate the issue: @JsonProperty with namespace and @JacksonXmlProperty without namespace.
    // We'll create two introspectors that mimic the behavior.
    @Test
    public void testMergeWithJsonPropertyAndJacksonXmlProperty() {
        // Introspector for @JsonProperty (handles namespace and value)
        AnnotationIntrospector jsonIntrospector = new AnnotationIntrospector() {
            @Override
            public PropertyName findNameForSerialization(Annotated a) {
                // Simulate @JsonProperty(namespace="uri:ns1", value="prop")
                return new PropertyName("prop", "uri:ns1");
            }

            @Override
            public PropertyName findNameForDeserialization(Annotated a) {
                return new PropertyName("prop", "uri:ns1");
            }

            @Override
            public Version version() {
                return Version.unknownVersion();
            }
        };

        // Introspector for @JacksonXmlProperty (handles isAttribute, but no namespace or local name specified)
        AnnotationIntrospector xmlIntrospector = new AnnotationIntrospector() {
            @Override
            public PropertyName findNameForSerialization(Annotated a) {
                // Simulate @JacksonXmlProperty(isAttribute=true) -> default empty name and namespace
                return new PropertyName("", "");
            }

            @Override
            public PropertyName findNameForDeserialization(Annotated a) {
                return new PropertyName("", "");
            }

            @Override
            public Version version() {
                return Version.unknownVersion();
            }
        };

        // Pair with json as primary and xml as secondary? Actually in the issue, the first introspector is the one for JacksonXmlProperty.
        // But the issue says first annotation has precedence (JacksonXmlProperty). So primary is xml introspector.
        // However, the issue states that currently the namespace and local name from @JsonProperty are not used.
        // With the fix, they should be merged: primary has empty, so secondary's non-empty should be used.
        AnnotationIntrospectorPair pair = new AnnotationIntrospectorPair(xmlIntrospector, jsonIntrospector);

        PropertyName result = pair.findNameForSerialization(null);
        assertNotNull(result);
        assertEquals("prop", result.getSimpleName());
        assertEquals("uri:ns1", result.getNamespace());

        result = pair.findNameForDeserialization(null);
        assertNotNull(result);
        assertEquals("prop", result.getSimpleName());
        assertEquals("uri:ns1", result.getNamespace());
    }
}

