package com.fasterxml.jackson.databind.deser.impl;

import com.fasterxml.jackson.annotation.JsonSetter;
import com.fasterxml.jackson.annotation.Nulls;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.Test;

import java.beans.ConstructorProperties;
import java.util.ArrayList;
import java.util.List;

import static org.junit.Assert.*;

public class FieldPropertySkipNullsTest {

    static class Outer {
        @JsonSetter(nulls = Nulls.SKIP)
        private final List<Middle> list1 = new ArrayList<>();

        public Outer() {
        }

        public List<Middle> getList1() {
            return list1;
        }
    }

    static class Middle {
        @JsonSetter(nulls = Nulls.SKIP)
        private final List<Inner> list1 = new ArrayList<>();
        private final String field1;

        @ConstructorProperties({"field1"})
        public Middle(String field1) {
            this.field1 = field1;
        }

        public List<Inner> getList1() {
            return list1;
        }

        public String getField1() {
            return field1;
        }
    }

    static class Inner {
        private final String field1;

        @ConstructorProperties({"field1"})
        public Inner(String field1) {
            this.field1 = field1;
        }

        public String getField1() {
            return field1;
        }
    }

    // Test class for non-skip nulls behavior
    static class TestClass {
        private List<String> values;

        public List<String> getValues() {
            return values;
        }

        public void setValues(List<String> values) {
            this.values = values;
        }
    }

    // Test class for multiple fields
    static class MultiField {
        @JsonSetter(nulls = Nulls.SKIP)
        private String field1;

        @JsonSetter(nulls = Nulls.SKIP)
        private Integer field2;

        private String field3; // No annotation

        public String getField1() { return field1; }
        public void setField1(String field1) { this.field1 = field1; }

        public Integer getField2() { return field2; }
        public void setField2(Integer field2) { this.field2 = field2; }

        public String getField3() { return field3; }
        public void setField3(String field3) { this.field3 = field3; }
    }

    // Test class for constructor and setter mix
    static class Mixed {
        private final String constructorField;

        @JsonSetter(nulls = Nulls.SKIP)
        private String setterField;

        @ConstructorProperties({"constructorField"})
        public Mixed(String constructorField) {
            this.constructorField = constructorField;
        }

        public String getConstructorField() { return constructorField; }
        public String getSetterField() { return setterField; }
        public void setSetterField(String setterField) { this.setterField = setterField; }
    }

    @Test
    public void testSkipNullsWithNestedLists() throws Exception {
        String json = "{\"list1\":[{\"list1\":null,\"field1\":\"data\"}]}";
        ObjectMapper objectMapper = new ObjectMapper();
        Outer outer = objectMapper.readValue(json, Outer.class);

        assertNotNull(outer);
        assertNotNull(outer.getList1());
        assertEquals(1, outer.getList1().size());

        Middle middle = outer.getList1().get(0);
        assertNotNull(middle);
        assertEquals("data", middle.getField1());
        assertNotNull(middle.getList1());
        assertTrue(middle.getList1().isEmpty());
    }

    @Test
    public void testSkipNullsOnFieldPropertySet() throws Exception {
        ObjectMapper mapper = new ObjectMapper();

        // Test with null value for field annotated with @JsonSetter(nulls = Nulls.SKIP)
        String json = "{\"list1\": null}";
        Outer outer = mapper.readValue(json, Outer.class);

        assertNotNull(outer);
        assertNotNull(outer.getList1());
        assertTrue(outer.getList1().isEmpty());
    }

    @Test
    public void testSkipNullsOnFieldPropertySetAndReturn() throws Exception {
        ObjectMapper mapper = new ObjectMapper();

        // Create an instance and verify setAndReturn behavior
        Outer outer = new Outer();
        String json = "{\"list1\": null}";
        Outer result = mapper.readerForUpdating(outer).readValue(json);

        assertSame(outer, result); // Should return same instance when skipping null
        assertNotNull(result.getList1());
        assertTrue(result.getList1().isEmpty());
    }

    @Test
    public void testNonSkipNullsBehavior() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        String json = "{\"values\": null}";
        TestClass obj = mapper.readValue(json, TestClass.class);

        assertNull(obj.getValues()); // Should be null since no @JsonSetter(nulls = Nulls.SKIP)
    }

    @Test
    public void testSkipNullsWithMultipleFields() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        String json = "{\"field1\": null, \"field2\": null, \"field3\": null}";
        MultiField obj = mapper.readValue(json, MultiField.class);

        // Fields with @JsonSetter(nulls = Nulls.SKIP) should keep their default values (null)
        assertNull(obj.getField1()); // default is null, skipped null set
        assertNull(obj.getField2()); // default is null, skipped null set
        assertNull(obj.getField3()); // should be null since no annotation
    }

    @Test
    public void testSkipNullsWithConstructorAndSetter() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        String json = "{\"constructorField\": \"test\", \"setterField\": null}";
        Mixed obj = mapper.readValue(json, Mixed.class);

        assertEquals("test", obj.getConstructorField());
        assertNull(obj.getSetterField()); // Should be skipped, so remains null
    }

    @Test
    public void testSkipNullsWithNonNullValue() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        String json = "{\"field1\": \"value\", \"field2\": 42, \"field3\": \"test\"}";
        MultiField obj = mapper.readValue(json, MultiField.class);

        assertEquals("value", obj.getField1());
        assertEquals(Integer.valueOf(42), obj.getField2());
        assertEquals("test", obj.getField3());
    }

    @Test
    public void testSkipNullsOnUpdateWithExistingValue() throws Exception {
        ObjectMapper mapper = new ObjectMapper();

        // Create object with existing values
        MultiField obj = new MultiField();
        obj.setField1("original");
        obj.setField2(100);
        obj.setField3("original3");

        // Update with null values
        String json = "{\"field1\": null, \"field2\": null, \"field3\": null}";
        MultiField updated = mapper.readerForUpdating(obj).readValue(json);

        assertSame(obj, updated);
        // Fields with @JsonSetter(nulls = Nulls.SKIP) should keep original values
        assertEquals("original", updated.getField1());
        assertEquals(Integer.valueOf(100), updated.getField2());
        // Field without annotation should be set to null
        assertNull(updated.getField3());
    }

    @Test
    public void testSkipNullsWithEmptyList() throws Exception {
        ObjectMapper mapper = new ObjectMapper();

        // Test with empty array (not null)
        String json = "{\"list1\": []}";
        Outer outer = mapper.readValue(json, Outer.class);

        assertNotNull(outer);
        assertNotNull(outer.getList1());
        assertTrue(outer.getList1().isEmpty());
    }

    @Test
    public void testSkipNullsWithComplexNestedStructure() throws Exception {
        String json = "{\"list1\":[{\"list1\":[{\"field1\":\"inner1\"}],\"field1\":\"middle1\"},{\"list1\":null,\"field1\":\"middle2\"}]}";
        ObjectMapper mapper = new ObjectMapper();
        Outer outer = mapper.readValue(json, Outer.class);

        assertNotNull(outer);
        assertNotNull(outer.getList1());
        assertEquals(2, outer.getList1().size());

        // First middle has non-null list
        Middle middle1 = outer.getList1().get(0);
        assertEquals("middle1", middle1.getField1());
        assertNotNull(middle1.getList1());
        assertEquals(1, middle1.getList1().size());
        assertEquals("inner1", middle1.getList1().get(0).getField1());

        // Second middle has null list (should be skipped)
        Middle middle2 = outer.getList1().get(1);
        assertEquals("middle2", middle2.getField1());
        assertNotNull(middle2.getList1());
        assertTrue(middle2.getList1().isEmpty());
    }
}

