package com.fasterxml.jackson.databind.node;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.Test;
import static org.junit.Assert.*;

public class ObjectNodeWithArrayPropertyTest {

    @Test
    public void testWithArrayPropertyWhenPropertyDoesNotExist() {
        ObjectNode objectNode = new ObjectNode(JsonNodeFactory.instance);
        ArrayNode result = objectNode.withArrayProperty("newArray");

        assertNotNull(result);
        assertTrue(result.isArray());
        assertEquals(0, result.size());
        assertTrue(objectNode.has("newArray"));
        assertSame(result, objectNode.get("newArray"));
    }

    @Test
    public void testWithArrayPropertyWhenPropertyIsNull() {
        ObjectNode objectNode = new ObjectNode(JsonNodeFactory.instance);
        objectNode.putNull("existingNull");

        ArrayNode result = objectNode.withArrayProperty("existingNull");

        assertNotNull(result);
        assertTrue(result.isArray());
        assertEquals(0, result.size());
        assertTrue(objectNode.has("existingNull"));
        assertSame(result, objectNode.get("existingNull"));
    }

    @Test
    public void testWithArrayPropertyWhenPropertyIsAlreadyArray() {
        ObjectNode objectNode = new ObjectNode(JsonNodeFactory.instance);
        ArrayNode existingArray = objectNode.putArray("existingArray");
        existingArray.add("value1");

        ArrayNode result = objectNode.withArrayProperty("existingArray");

        assertNotNull(result);
        assertSame(existingArray, result);
        assertEquals(1, result.size());
        assertEquals("value1", result.get(0).asText());
    }

    @Test
    public void testWithArrayPropertyWhenPropertyIsObject() {
        ObjectNode objectNode = new ObjectNode(JsonNodeFactory.instance);
        objectNode.putObject("existingObject");

        try {
            objectNode.withArrayProperty("existingObject");
            fail("Should have thrown UnsupportedOperationException");
        } catch (UnsupportedOperationException e) {
            // Expected - thrown by _reportWrongNodeType
            assertTrue(e.getMessage().contains("Cannot replace"));
            assertTrue(e.getMessage().contains("ObjectNode"));
            assertTrue(e.getMessage().contains("existingObject"));
            assertTrue(e.getMessage().contains("OverwriteMode.NULLS"));
        }
    }

    @Test
    public void testWithArrayPropertyWhenPropertyIsText() {
        ObjectNode objectNode = new ObjectNode(JsonNodeFactory.instance);
        objectNode.put("existingText", "some text");

        try {
            objectNode.withArrayProperty("existingText");
            fail("Should have thrown UnsupportedOperationException");
        } catch (UnsupportedOperationException e) {
            // Expected - thrown by _reportWrongNodeType
            assertTrue(e.getMessage().contains("Cannot replace"));
            assertTrue(e.getMessage().contains("TextNode"));
            assertTrue(e.getMessage().contains("existingText"));
            assertTrue(e.getMessage().contains("OverwriteMode.NULLS"));
        }
    }

    @Test
    public void testWithArrayPropertyWhenPropertyIsNumber() {
        ObjectNode objectNode = new ObjectNode(JsonNodeFactory.instance);
        objectNode.put("existingNumber", 42);

        try {
            objectNode.withArrayProperty("existingNumber");
            fail("Should have thrown UnsupportedOperationException");
        } catch (UnsupportedOperationException e) {
            // Expected - thrown by _reportWrongNodeType
            assertTrue(e.getMessage().contains("Cannot replace"));
            assertTrue(e.getMessage().contains("IntNode"));
            assertTrue(e.getMessage().contains("existingNumber"));
            assertTrue(e.getMessage().contains("OverwriteMode.NULLS"));
        }
    }

    @Test
    public void testWithArrayPropertyWhenPropertyIsBoolean() {
        ObjectNode objectNode = new ObjectNode(JsonNodeFactory.instance);
        objectNode.put("existingBoolean", true);

        try {
            objectNode.withArrayProperty("existingBoolean");
            fail("Should have thrown UnsupportedOperationException");
        } catch (UnsupportedOperationException e) {
            // Expected - thrown by _reportWrongNodeType
            assertTrue(e.getMessage().contains("Cannot replace"));
            assertTrue(e.getMessage().contains("BooleanNode"));
            assertTrue(e.getMessage().contains("existingBoolean"));
            assertTrue(e.getMessage().contains("OverwriteMode.NULLS"));
        }
    }

    @Test
    public void testWithArrayPropertyOnNonObjectNode() {
