package com.fasterxml.jackson.databind;

import com.fasterxml.jackson.databind.cfg.MapperConfig;
import com.fasterxml.jackson.databind.introspect.*;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import java.lang.annotation.Annotation;
import java.util.Objects;

import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.when;

/**
 * Tests for {@link PropertyName} and {@link AnnotationIntrospectorPair} merging functionality.
 */
public class PropertyNameMergeTest {

    // Simple helper to create AnnotatedField without complex setup
    private AnnotatedField createAnnotatedField() {
        try {
            class Dummy {
                @SuppressWarnings("unused")
                public String field;
            }
            // Use simpler approach with Java's reflection
            return new AnnotatedField(null, 
                Dummy.class.getDeclaredField("field"), 
                null);
        } catch (NoSuchFieldException e) {
            throw new RuntimeException(e);
        }
    }

    // Test the new merge method thoroughly
    @Test
    public void testPropertyNameMerge() {
        // Both null -> null
        assertNull(PropertyName.merge(null, null));

        // One null, other non-null
        PropertyName name = new PropertyName("simple");
        assertEquals(name, PropertyName.merge(null, name));
        assertEquals(name, PropertyName.merge(name, null));

        // Both non-null, primary has empty simple name, secondary has simple name
        PropertyName emptySimple = new PropertyName("", "ns1");
        PropertyName withSimple = new PropertyName("simple", null);
        PropertyName merged = PropertyName.merge(emptySimple, withSimple);
        assertEquals("simple", merged.getSimpleName());
        assertEquals("ns1", merged.getNamespace());

        // Both non-null, primary has empty namespace, secondary has namespace
        PropertyName emptyNs = new PropertyName("simple", "");
        PropertyName withNs = new PropertyName(null, "ns2");
        merged = PropertyName.merge(emptyNs, withNs);
        assertEquals("simple", merged.getSimpleName());
        assertEquals("ns2", merged.getNamespace());

        // Primary has both, secondary has empty -> primary
        PropertyName full = new PropertyName("simple", "ns");
        PropertyName emptyBoth = new PropertyName("", "");
        merged = PropertyName.merge(full, emptyBoth);
        assertEquals("simple", merged.getSimpleName());
        assertEquals("ns", merged.getNamespace());

        // Secondary has both, primary has empty -> secondary
        merged = PropertyName.merge(emptyBoth, full);
        assertEquals("simple", merged.getSimpleName());
        assertEquals("ns", merged.getNamespace());

        // Both have non-empty, first argument takes precedence
        PropertyName first = new PropertyName("firstSimple", "firstNs");
        PropertyName second = new PropertyName("secondSimple", "secondNs");
        merged = PropertyName.merge(first, second);
        assertEquals("firstSimple", merged.getSimpleName());
        assertEquals("firstNs", merged.getNamespace());

        // Test with null namespace
        PropertyName noNamespace = new PropertyName("name", null);
        PropertyName withNamespace = new PropertyName("name", "ns");
        merged = PropertyName.merge(noNamespace, withNamespace);
        assertEquals("name", merged.getSimpleName());
        assertEquals("ns", merged.getNamespace());

        // Test with empty string vs null namespace
        PropertyName emptyStringNs = new PropertyName("name", "");
        merged = PropertyName.merge(emptyStringNs, withNamespace);
        assertEquals("name", merged.getSimpleName());
        assertEquals("ns", merged.getNamespace()); // Empty string is considered empty, so use secondary

        // Test USE_DEFAULT handling
        PropertyName useDefault = PropertyName.USE_DEFAULT;
        PropertyName explicit = new PropertyName("explicit", "ns");
        merged = PropertyName.merge(useDefault, explicit);
        assertEquals("explicit", merged.getSimpleName());
        assertEquals("ns", merged.getNamespace());

        // The other way around: explicit first, USE_DEFAULT second
        merged = PropertyName.merge(explicit, useDefault);
        assertEquals("explicit", merged.getSimpleName());
        assertEquals("ns", merged.getNamespace());

        // Test NO_NAME
        PropertyName noName = PropertyName.NO_NAME;
        merged = PropertyName.merge(noName, explicit);
        assertEquals("explicit", merged.getSimpleName());
        assertEquals("ns", merged.getNamespace());

