        // Test textual null values
        mapper.coercionConfigFor(LogicalType.Float)
                .setCoercion(CoercionInputShape.String, CoercionAction.AsNull);

        // Test with "null" string
        FloatWrapper result = mapper.readValue("{\"value\": \"null\"}", FloatWrapper.class);
        assertNull(result.value);
    }

    @Test
    public void testFloatCoercionConfigForFloatInput() throws Exception {
        ObjectMapper mapper = new ObjectMapper();

        // The patch only affects integer-to-float coercion, not float-to-float
        // So float inputs should still work normally regardless of integer coercion config
        mapper.coercionConfigFor(LogicalType.Float)
                .setCoercion(CoercionInputShape.Integer, CoercionAction.Fail);

        // Float input should still work
        FloatWrapper result = mapper.readValue("{\"value\": 42.5}", FloatWrapper.class);
        assertEquals(42.5f, result.value, 0.0f);

        // Integer input should fail
        try {
            mapper.readValue("{\"value\": 42}", FloatWrapper.class);
            fail("Expected MismatchedInputException for integer");
        } catch (MismatchedInputException e) {
            // expected
        }
    }

    @Test
    public void testPrimitiveFloatCoercionConfig() throws Exception {
        ObjectMapper mapper = new ObjectMapper();

        // Test primitive float with different coercion actions
        mapper.coercionConfigFor(LogicalType.Float)
                .setCoercion(CoercionInputShape.Integer, CoercionAction.AsNull);

        PrimitiveFloatWrapper result = mapper.readValue("{\"value\": 42}", PrimitiveFloatWrapper.class);
        assertEquals(0.0f, result.value, 0.0f);

        // Change to AsEmpty (should be same result for primitive)
        mapper.coercionConfigFor(LogicalType.Float)
                .setCoercion(CoercionInputShape.Integer, CoercionAction.AsEmpty);

        PrimitiveFloatWrapper result2 = mapper.readValue("{\"value\": 42}", PrimitiveFloatWrapper.class);
        assertEquals(0.0f, result2.value, 0.0f);

        // Change to Fail
        mapper.coercionConfigFor(LogicalType.Float)
                .setCoercion(CoercionInputShape.Integer, CoercionAction.Fail);

        try {
            mapper.readValue("{\"value\": 42}", PrimitiveFloatWrapper.class);
            fail("Expected MismatchedInputException");
        } catch (MismatchedInputException e) {
            // expected
        }
    }

    @Test
    public void testBigDecimalCoercionConfigForFloatInput() throws Exception {
        ObjectMapper mapper = new ObjectMapper();

        // BigDecimal should also respect integer coercion config
        mapper.coercionConfigFor(LogicalType.Float)
                .setCoercion(CoercionInputShape.Integer, CoercionAction.Fail);

        // Integer input should fail
        try {
            mapper.readValue("{\"value\": 42}", BigDecimalWrapper.class);
            fail("Expected MismatchedInputException");
        } catch (MismatchedInputException e) {
            // expected
        }

        // Float input should still work
        BigDecimalWrapper result = mapper.readValue("{\"value\": 42.5}", BigDecimalWrapper.class);
        assertEquals(new BigDecimal("42.5"), result.value);
    }

    @Test
    public void testCoercionActionFallThrough() throws Exception {
        ObjectMapper mapper = new ObjectMapper();

        // Test that when coercion action is not AsNull or AsEmpty, it falls through to normal coercion
        // Default action (TryConvert) should allow coercion
        mapper.coercionConfigFor(LogicalType.Float)
                .setCoercion(CoercionInputShape.Integer, CoercionAction.TryConvert);

        FloatWrapper result = mapper.readValue("{\"value\": 42}", FloatWrapper.class);
        assertEquals(42.0f, result.value, 0.0f);

        // Same for Double
        DoubleWrapper result2 = mapper.readValue("{\"value\": 42}", DoubleWrapper.class);
        assertEquals(42.0, result2.value, 0.0);

        // Same for BigDecimal
        BigDecimalWrapper result3 = mapper.readValue("{\"value\": 42}", BigDecimalWrapper.class);
        assertEquals(BigDecimal.valueOf(42), result3.value);
    }
}

