        );
    }

    // Test to cover the copy constructor with ignorable properties (modified by patch)
    @Test
    public void testWithIgnorableProperties() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        // This should trigger the copy constructor with ignorable properties
        // which was missing _externalTypeIdHandler copy before the patch
        // Note: "extra" field is not marked as ignorable, so we need to adjust the test
        String json = "{\"child\":{\"childType\":\"A\", \"subChild\": {\"aField\":\"ignorable\"}, \"parent\":\"ignored\"}}";
        Parent parent = mapper.readValue(json, Parent.class);
        assertNotNull(parent);
        assertNotNull(parent.child);
        assertEquals("A", parent.child.childType);
        assertTrue(parent.child.subChild instanceof SubChildA);
        assertEquals("ignorable", ((SubChildA) parent.child.subChild).aField);
    }

    // Test to cover the copy constructor with NameTransformer (has uncovered line)
    @Test
