        // Enable unwrapping to trigger NameTransformer constructor
        mapper.enable(com.fasterxml.jackson.databind.DeserializationFeature.UNWRAP_ROOT_VALUE);

        // Create JSON with root wrapper
        String json = "{\"Parent\":{\"child\":{\"childType\":\"B\", \"subChild\": {\"bField\":999}, \"parent\":null}}}";

        // Read with unwrapping
        Parent parent = mapper.readerFor(Parent.class)
                .withRootName("Parent")
                .readValue(json);

        assertNotNull(parent);
        assertNotNull(parent.child);
        assertEquals("B", parent.child.childType);
        assertTrue(parent.child.subChild instanceof SubChildB);
        assertEquals(999, ((SubChildB) parent.child.subChild).bField);
    }

