        @JsonTypeInfo(
                use = JsonTypeInfo.Id.NAME,
                include = JsonTypeInfo.As.EXTERNAL_PROPERTY,
                property = "type2"
        )
        @JsonSubTypes({
                @JsonSubTypes.Type(name = "Y", value = TypeY.class),
        })
        public Object obj2;
    }

    static class TypeX {
        public String x;
    }

    static class TypeY {
        public int y;
    }

    static class MultiParent {
        @JsonIgnoreProperties({"type2", "obj2"})
        public MultiTypeChild child;
    }

    @Test
    public void testMultipleExternalTypeIdsWithIgnore() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        // This tests that multiple external type handlers work correctly
        // when some properties are ignored
        MultiParent parent = mapper.readValue(
                "{\"child\":{\"type1\":\"X\", \"obj1\": {\"x\":\"testX\"}}}",
                MultiParent.class
        );
        assertNotNull(parent);
        assertNotNull(parent.child);
        assertEquals("X", parent.child.type1);
        assertTrue(parent.child.obj1 instanceof TypeX);
        assertEquals("testX", ((TypeX) parent.child.obj1).x);
    }

    // New test to cover the uncovered line in NameTransformer constructor
    @Test
    public void testNameTransformerConstructorWithoutUnwrapper() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        // This test ensures that when unwrapper is null, the _beanProperties assignment
        // (the uncovered line) is executed
        // We'll test with a simple Child deserialization without unwrapping
        Child child = mapper.readValue(
                "{\"childType\":\"A\", \"subChild\": {\"aField\":\"noUnwrap\"}}",
                Child.class
        );
        assertNotNull(child);
        assertEquals("A", child.childType);
        assertTrue(child.subChild instanceof SubChildA);
        assertEquals("noUnwrap", ((SubChildA) child.subChild).aField);
    }

    // Test to verify the patch fixes all copy constructors
    @Test
    public void testAllCopyConstructorsPreserveExternalTypeIdHandler() throws Exception {
        ObjectMapper mapper = new ObjectMapper();

        // Test 1: Original bug scenario
        Parent parent1 = mapper.readValue(
                "{\"child\":{\"childType\":\"A\", \"subChild\": {\"aField\":\"test1\"}, \"parent\":null}}",
                Parent.class
        );
        assertNotNull(parent1.child.subChild);

        // Test 2: With different type
        Parent parent2 = mapper.readValue(
                "{\"child\":{\"childType\":\"B\", \"subChild\": {\"bField\":100}, \"parent\":null}}",
                Parent.class
        );
        assertNotNull(parent2.child.subChild);

        // Test 3: Direct Child deserialization
        Child child = mapper.readValue(
                "{\"childType\":\"A\", \"subChild\": {\"aField\":\"test3\"}}",
                Child.class
        );
        assertNotNull(child.subChild);

        // All should work without throwing exceptions about missing creators
    }
}

