package com.fasterxml.jackson.databind.deser.std;

import com.fasterxml.jackson.databind.DeserializationConfig;
import com.fasterxml.jackson.databind.DeserializationContext;
import com.fasterxml.jackson.databind.DeserializationFeature;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.cfg.CoercionAction;
import com.fasterxml.jackson.databind.cfg.CoercionInputShape;
import com.fasterxml.jackson.databind.exc.MismatchedInputException;
import com.fasterxml.jackson.databind.json.JsonMapper;
import com.fasterxml.jackson.databind.type.TypeFactory;
import org.junit.Test;

import java.io.IOException;
import java.util.Date;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import static org.junit.Assert.fail;

public class StdDeserializerNestedArrayTest {

    private final ObjectMapper mapper = new ObjectMapper();

    // Helper POJO for testing primitive deserialization
    static class PrimitiveBean {
        public boolean booleanValue;
        public byte byteValue;
        public short shortValue;
        public int intValue;
        public long longValue;
        public float floatValue;
        public double doubleValue;
        public Date dateValue;
    }

    @Test
    public void testUnwrapSingleValueArrayForBoolean() throws IOException {
        mapper.enable(DeserializationFeature.UNWRAP_SINGLE_VALUE_ARRAYS);
        PrimitiveBean bean = mapper.readValue("{\"booleanValue\":[true]}", PrimitiveBean.class);
        assertEquals(true, bean.booleanValue);
    }

    @Test
    public void testUnwrapSingleValueArrayForByte() throws IOException {
        mapper.enable(DeserializationFeature.UNWRAP_SINGLE_VALUE_ARRAYS);
        PrimitiveBean bean = mapper.readValue("{\"byteValue\":[42]}", PrimitiveBean.class);
        assertEquals((byte)42, bean.byteValue);
    }

    @Test
    public void testUnwrapSingleValueArrayForShort() throws IOException {
        mapper.enable(DeserializationFeature.UNWRAP_SINGLE_VALUE_ARRAYS);
        PrimitiveBean bean = mapper.readValue("{\"shortValue\":[1234]}", PrimitiveBean.class);
        assertEquals((short)1234, bean.shortValue);
    }

    @Test
    public void testUnwrapSingleValueArrayForInt() throws IOException {
        mapper.enable(DeserializationFeature.UNWRAP_SINGLE_VALUE_ARRAYS);
        PrimitiveBean bean = mapper.readValue("{\"intValue\":[5678]}", PrimitiveBean.class);
        assertEquals(5678, bean.intValue);
    }

    @Test
    public void testUnwrapSingleValueArrayForLong() throws IOException {
        mapper.enable(DeserializationFeature.UNWRAP_SINGLE_VALUE_ARRAYS);
        PrimitiveBean bean = mapper.readValue("{\"longValue\":[9876543210]}", PrimitiveBean.class);
        assertEquals(9876543210L, bean.longValue);
    }

    @Test
    public void testUnwrapSingleValueArrayForFloat() throws IOException {
        mapper.enable(DeserializationFeature.UNWRAP_SINGLE_VALUE_ARRAYS);
        PrimitiveBean bean = mapper.readValue("{\"floatValue\":[3.14]}", PrimitiveBean.class);
        assertEquals(3.14f, bean.floatValue, 0.001f);
    }

    @Test
    public void testUnwrapSingleValueArrayForDouble() throws IOException {
        mapper.enable(DeserializationFeature.UNWRAP_SINGLE_VALUE_ARRAYS);
        PrimitiveBean bean = mapper.readValue("{\"doubleValue\":[2.718]}", PrimitiveBean.class);
        assertEquals(2.718, bean.doubleValue, 0.001);
    }

    @Test
    public void testUnwrapSingleValueArrayForDate() throws IOException {
        mapper.enable(DeserializationFeature.UNWRAP_SINGLE_VALUE_ARRAYS);
        // Use a timestamp that Jackson can parse by default
        long timestamp = 1665000000000L;
        PrimitiveBean bean = mapper.readValue("{\"dateValue\":[" + timestamp + "]}", PrimitiveBean.class);
        assertEquals(new Date(timestamp), bean.dateValue);
    }

    // Test empty array coercion for Date with AsEmpty (FIXED: getEmptyValue returns Date(0) not null)
    @Test
    public void testEmptyArrayForDateWithAsEmptyCoercion() throws IOException {
        ObjectMapper mapperWithCoercion = JsonMapper.builder()
                .withCoercionConfigDefaults(config -> {
                    config.setCoercion(CoercionInputShape.EmptyArray, CoercionAction.AsEmpty);
                })
                .build();

        PrimitiveBean bean = mapperWithCoercion.readValue("{\"dateValue\":[]}", PrimitiveBean.class);
        // AsEmpty returns getEmptyValue() which for Date is new Date(0L)
        assertEquals(new Date(0L), bean.dateValue);
    }

    // Test empty array coercion for Date with AsNull
    @Test
    public void testEmptyArrayForDateWithAsNullCoercion() throws IOException {
        ObjectMapper mapperWithCoercion = JsonMapper.builder()
                .withCoercionConfigDefaults(config -> {
                    config.setCoercion(CoercionInputShape.EmptyArray, CoercionAction.AsNull);
                })
                .build();

        PrimitiveBean bean = mapperWithCoercion.readValue("{\"dateValue\":[]}", PrimitiveBean.class);
        assertNull(bean.dateValue);
    }

    // Test empty array for Date with TryConvert
    @Test
    public void testEmptyArrayForDateWithTryConvertCoercion() throws IOException {
        ObjectMapper mapperWithCoercion = JsonMapper.builder()
                .withCoercionConfigDefaults(config -> {
                    config.setCoercion(CoercionInputShape.EmptyArray, CoercionAction.TryConvert);
                })
                .build();

        PrimitiveBean bean = mapperWithCoercion.readValue("{\"dateValue\":[]}", PrimitiveBean.class);
        assertNull(bean.dateValue);
    }

    // Test empty array for Date with Fail (default) - covers last uncovered line
    @Test
    public void testEmptyArrayForDateWithFailCoercion() throws IOException {
        // Default mapper has Fail coercion for empty arrays
        try {
            mapper.readValue("{\"dateValue\":[]}", PrimitiveBean.class);
            fail("Expected exception for empty array");
        } catch (MismatchedInputException e) {
            // Expected - this covers the last uncovered line
            assertTrue(e.getMessage().contains("Cannot deserialize"));
        }
    }

    // Test nested array for Date with UNWRAP_SINGLE_VALUE_ARRAYS enabled - covers the uncovered line
    @Test
    public void testNestedArrayForDateWithUnwrapEnabled() throws IOException {
        mapper.enable(DeserializationFeature.UNWRAP_SINGLE_VALUE_ARRAYS);
        long timestamp = 1665000000000L;
        try {
            mapper.readValue("{\"dateValue\":[[" + timestamp + "]]}", PrimitiveBean.class);
            fail("Expected exception for nested array");
        } catch (MismatchedInputException e) {
            assertTrue(e.getMessage().contains("nested Arrays not allowed"));
        }
    }

    // Test nested array for Date with UNWRAP_SINGLE_VALUE_ARRAYS disabled
    @Test
    public void testNestedArrayForDateWithoutUnwrapEnabled() throws IOException {
        mapper.disable(DeserializationFeature.UNWRAP_SINGLE_VALUE_ARRAYS);
        long timestamp = 1665000000000L;
        try {
            mapper.readValue("{\"dateValue\":[[" + timestamp + "]]}", PrimitiveBean.class);
            fail("Expected exception for array");
        } catch (MismatchedInputException e) {
            // Should fail but with different error message
        }
    }

    // Now test nested arrays (should fail with the new patch)

    @Test
    public void testNestedArrayForBoolean() throws IOException {
        mapper.enable(DeserializationFeature.UNWRAP_SINGLE_VALUE_ARRAYS);
        try {
            mapper.readValue("{\"booleanValue\":[[true]]}", PrimitiveBean.class);
            fail("Expected exception for nested array");
        } catch (MismatchedInputException e) {
            assertTrue(e.getMessage().contains("nested Arrays not allowed"));
        }
    }

    @Test
