        try {
            mapper.readValue("{\"shortValue\":[[1234]]}", PrimitiveBean.class);
            fail("Expected exception for nested array");
        } catch (MismatchedInputException e) {
            assertTrue(e.getMessage().contains("nested Arrays not allowed"));
        }
    }

    @Test
    public void testNestedArrayForInt() throws IOException {
