        try {
            mapper.readValue("{\"longValue\":[[9876543210]]}", PrimitiveBean.class);
            fail("Expected exception for nested array");
        } catch (MismatchedInputException e) {
            assertTrue(e.getMessage().contains("nested Arrays not allowed"));
        }
    }

    @Test
    public void testNestedArrayForFloat() throws IOException {
        mapper.enable(DeserializationFeature.UNWRAP_SINGLE_VALUE_ARRAYS);
        try {
            mapper.readValue("{\"floatValue\":[[3.14]]}", PrimitiveBean.class);
            fail("Expected exception for nested array");
        } catch (MismatchedInputException e) {
            assertTrue(e.getMessage().contains("nested Arrays not allowed"));
        }
    }

    @Test
    public void testNestedArrayForDouble() throws IOException {
        mapper.enable(DeserializationFeature.UNWRAP_SINGLE_VALUE_ARRAYS);
        try {
            mapper.readValue("{\"doubleValue\":[[2.718]]}", PrimitiveBean.class);
            fail("Expected exception for nested array");
        } catch (MismatchedInputException e) {
            assertTrue(e.getMessage().contains("nested Arrays not allowed"));
        }
    }

    // Test triple nested array (should also fail)
    @Test
    public void testTripleNestedArrayForInt() throws IOException {
        mapper.enable(DeserializationFeature.UNWRAP_SINGLE_VALUE_ARRAYS);
        try {
            mapper.readValue("{\"intValue\":[[[5678]]]}", PrimitiveBean.class);
            fail("Expected exception for nested array");
        } catch (MismatchedInputException e) {
            assertTrue(e.getMessage().contains("nested Arrays not allowed"));
        }
    }

    // Test multiple levels of nesting for all types
    @Test
    public void testMultipleLevelsOfNesting() throws IOException {
        mapper.enable(DeserializationFeature.UNWRAP_SINGLE_VALUE_ARRAYS);

        // Test with increasing levels of nesting for different types
        String[][] testCases = {
            {"booleanValue", "[[true]]"},
            {"byteValue", "[[42]]"},
            {"shortValue", "[[1234]]"},
            {"intValue", "[[5678]]"},
            {"longValue", "[[9876543210]]"},
            {"floatValue", "[[3.14]]"},
            {"doubleValue", "[[2.718]]"},
            {"dateValue", "[[1665000000000]]"}
        };

        for (String[] testCase : testCases) {
            String field = testCase[0];
            String value = testCase[1];
            String json = String.format("{\"%s\":%s}", field, value);
            try {
                mapper.readValue(json, PrimitiveBean.class);
                fail("Expected exception for nested array in: " + json);
            } catch (MismatchedInputException e) {
                assertTrue("Message should mention nested arrays: " + e.getMessage(),
                    e.getMessage().contains("nested Arrays not allowed"));
            }
        }
    }

    // Test that non-array values still work with UNWRAP_SINGLE_VALUE_ARRAYS enabled
    @Test
